  anchor.href = url; anchor.download = filename.split('').map(c => c.charCodeAt(0) < 32 || c === '/' || c === '\\' ? '_' : c).join('') || 'attachment';
  document.body.append(anchor); anchor.click(); anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// Also clear resources for session transitions initiated outside the main store.
onAuthEpochChange(clearAttachmentCache);

const downloads = new Set<AbortController>();
/** Explicit original-byte downloads are never inserted into the preview cache. */
export async function fetchOriginalAttachment(path: string, epoch: number, signal: AbortSignal): Promise<Blob> {
  signal.throwIfAborted();
  if (!isCurrentAuthEpoch(epoch)) throw new DOMException('Cancelled', 'AbortError');
  if (downloads.size >= 2) throw new Error('LIMIT');
  const controller = new AbortController(); const abort = () => controller.abort();
  downloads.add(controller); signal.addEventListener('abort', abort, { once: true });
  try {
    const blob = await readBlob(path, controller.signal, undefined, false);
    controller.signal.throwIfAborted();
    if (!isCurrentAuthEpoch(epoch)) throw new DOMException('Cancelled', 'AbortError');
    return blob;
  } finally { signal.removeEventListener('abort', abort); downloads.delete(controller); }
}
onAuthEpochChange(() => { for (const controller of downloads) controller.abort(); });

import type { StoreApi } from 'zustand';
import type { StoreState } from './index.ts';
import type { AttachmentSelection, AttachmentWindow } from '../utils/attachments/types.ts';
export interface AttachmentState {
  attachmentPreview: AttachmentSelection | null;
  attachmentWindows: AttachmentWindow[];
  openAttachmentPreview: (selection: AttachmentSelection) => void;
  closeAttachmentPreview: () => void;
  selectAttachmentPreview: (index: number) => void;
  selectAttachmentWindow: (id: string, index: number) => void;
  detachAttachmentPreview: () => void;
  restoreAttachmentWindow: (id: string) => void;
  closeAttachmentWindow: (id: string) => void;
  focusAttachmentWindow: (id: string) => void;
  minimizeAttachmentWindow: (id: string, minimized: boolean) => void;
  updateAttachmentWindowRect: (id: string, rect: { x: number; y: number; w: number; h: number }) => void;
}
/** Ephemeral descriptors only: blobs/passwords never enter the store or preferences. */
export function createAttachmentSlice(set: StoreApi<StoreState>['setState'], get: StoreApi<StoreState>['getState']): AttachmentState {
  return {
    attachmentPreview: null, attachmentWindows: [],
    openAttachmentPreview: selection => {
      if (selection.authEpoch === get().authEpoch && selection.attachments[selection.index]) set({ attachmentPreview: selection });
    },
    closeAttachmentPreview: () => set({ attachmentPreview: null }),
    selectAttachmentPreview: index => set(state => {
      const selection = state.attachmentPreview;
      return selection && selection.authEpoch === state.authEpoch && selection.attachments[index]
        ? { attachmentPreview: { ...selection, index } } : {};
    }),
    selectAttachmentWindow: (id, index) => set(state => ({ attachmentWindows: state.attachmentWindows.map(win =>
      win.id === id && win.selection.authEpoch === state.authEpoch && win.selection.attachments[index]
        ? { ...win, selection: { ...win.selection, index } } : win) })),
    detachAttachmentPreview: () => set(state => {
      const selection = state.attachmentPreview;
      if (!selection || selection.authEpoch !== state.authEpoch || state.attachmentWindows.length >= 4) return {};
      const existing = state.attachmentWindows.find(window => window.selection.attachments[window.selection.index]?.path === selection.attachments[selection.index]?.path);
      const seq = state._winSeq + 1;
      if (existing) return { attachmentPreview: null, _winSeq: seq, attachmentWindows: state.attachmentWindows.map(window => window.id === existing.id ? { ...window, minimized: false, z: seq } : window) };
      const w = Math.min(960, window.innerWidth - 48); const h = Math.min(780, window.innerHeight - 80);
      return { attachmentPreview: null, _winSeq: seq, attachmentWindows: [...state.attachmentWindows, {
        id: `aw-${seq}`, selection, x: Math.max(12, (window.innerWidth - w) / 2), y: 40, w, h, z: seq, minimized: false,
      }] };
    }),
    restoreAttachmentWindow: id => set(state => {
      const win = state.attachmentWindows.find(item => item.id === id);
      return win && win.selection.authEpoch === state.authEpoch ? {
        attachmentPreview: win.selection,
        attachmentWindows: state.attachmentWindows.filter(item => item.id !== id),
      } : {};
    }),
    closeAttachmentWindow: id => set(state => ({ attachmentWindows: state.attachmentWindows.filter(window => window.id !== id) })),
    focusAttachmentWindow: id => set(state => ({ _winSeq: state._winSeq + 1, attachmentWindows: state.attachmentWindows.map(window => window.id === id ? { ...window, z: state._winSeq + 1 } : window) })),
    minimizeAttachmentWindow: (id, minimized) => set(state => ({ _winSeq: state._winSeq + 1, attachmentWindows: state.attachmentWindows.map(window => window.id === id ? { ...window, minimized, z: state._winSeq + 1 } : window) })),
    updateAttachmentWindowRect: (id, rect) => set(state => ({ attachmentWindows: state.attachmentWindows.map(window => window.id === id ? { ...window, ...rect } : window) })),
  };
}

/** The account fields the unified-inbox helpers read. */
type UnifiedInboxAccountLike = {
  id: string;
  enabled?: boolean;
  include_in_unified_inbox?: boolean;
  [key: string]: unknown;
};

export function isAccountInUnifiedInbox(account: UnifiedInboxAccountLike | undefined) {
  return !!account?.enabled && account.include_in_unified_inbox !== false;
}

export function accountAffectsUnifiedInbox(accounts: UnifiedInboxAccountLike[], accountId: string): boolean {
  const account = accounts.find(candidate => candidate.id === accountId);
  return isAccountInUnifiedInbox(account);
}

export function unifiedUnreadTotal(byAccount: Record<string, number>, accounts: UnifiedInboxAccountLike[]): number {
  return accounts.reduce((total, account) => (
    isAccountInUnifiedInbox(account)
      ? total + (Number(byAccount[account.id]) || 0)
      : total
  ), 0);
}

/** A request belongs to the navigation which started it, not merely its React effect. */
export interface MailViewScope {
  authEpoch: number;
  selectedAccountId: string | null;
  selectedFolder: string;
  messagesRefreshToken: number;
}
export function mailViewScopeMatches(current: MailViewScope & { isLocked?: boolean }, expected: MailViewScope): boolean {
  return !current.isLocked && current.authEpoch === expected.authEpoch
    && current.selectedAccountId === expected.selectedAccountId
    && current.selectedFolder === expected.selectedFolder
    && current.messagesRefreshToken === expected.messagesRefreshToken;
}

/** Rollbacks may restore rows only to the mailbox which currently displays them. */
export function messageMatchesMailbox(row: { account_id?: unknown; folder?: unknown; folder_paths?: unknown; is_archived?: unknown },
  state: { selectedAccountId: string | null; selectedFolder: string; accounts: readonly { id: string; enabled?: boolean; include_in_unified_inbox?: boolean }[] }): boolean {
  if (state.selectedAccountId && row.account_id !== state.selectedAccountId) return false;
  if (!state.selectedAccountId) {
    const account = state.accounts.find(account => account.id === row.account_id);
    if (account?.enabled === false || account?.include_in_unified_inbox === false) return false;
  }
  const folder = state.selectedAccountId ? state.selectedFolder : 'INBOX';
  if (folder === 'Archive') return row.folder === folder || row.is_archived === true;
  if (row.is_archived === true) return false;
  return row.folder === undefined || row.folder === folder
    || (Array.isArray(row.folder_paths) && row.folder_paths.includes(folder));
}

// A provider copy is actionable by physical ID; an RFC header is not an identity.
type NativeThreadMember = {
  id?: unknown;
  message_id?: unknown;
  messageId?: unknown;
  logical_message_id?: unknown;
  logicalMessageId?: unknown;
  account_id?: unknown;
};

function membershipKey(message: NativeThreadMember): string {
  return `physical:${String(message.account_id || '')}:${String(message.id || '')}`;
}

function displayMembershipKey(message: NativeThreadMember): string {
  const account = String(message.account_id || '');
  const logicalMessageId = String(message.logical_message_id || message.logicalMessageId || '').trim();
  if (logicalMessageId) return `logical:${account}:${logicalMessageId}`;
  const messageId = String(message.message_id || message.messageId || '').trim().toLowerCase();
  if (messageId) return `message-id:${account}:${messageId}`;
  return membershipKey(message);
}

function isNativeThreadMember(value: unknown): value is NativeThreadMember {
  return (typeof value === 'object' && value !== null) || typeof value === 'function';
}

export function normalizedNativeThreadMembers<T>(messages: readonly T[] | null | undefined | false | 0 | ''): T[] {
  const members = new Map<string, T>();
  if (messages === null || messages === undefined || messages === false || messages === 0 || messages === '') return [];
  for (const message of messages) {
    if (!isNativeThreadMember(message) || !message.id) continue;
    const key = membershipKey(message);
    if (!members.has(key)) members.set(key, message);
  }
  return Array.from(members.values());
}

/**
 * Collapse physical folder/provider copies into one row for thread presentation.
 * Action membership deliberately remains physical via normalizedNativeThreadMembers().
 */
export function normalizedNativeThreadDisplayMembers<T>(messages: readonly T[] | null | undefined | false | 0 | ''): T[] {
  const members = new Map<string, T>();
  if (messages === null || messages === undefined || messages === false || messages === 0 || messages === '') return [];
  for (const message of messages) {
    if (!isNativeThreadMember(message) || !message.id) continue;
    const key = displayMembershipKey(message);
    if (!members.has(key)) members.set(key, message);
  }
  return Array.from(members.values());
}

export function isExpandableNativeThread<T>(messages: readonly T[] | null | undefined | false | 0 | ''): boolean {
  return normalizedNativeThreadMembers(messages).length > 1;
}

export function singletonNativeThreadTarget<T>(row: T | null | undefined, normalizedMembers: readonly T[]): T | null {
  if (isNativeThreadMember(row)) {
    for (const member of normalizedMembers) {
      if (isNativeThreadMember(member) && String(member.id) === String(row.id)) return member;
    }
  }
  if (row) return row;
  return normalizedMembers[0] || null;
}

/** A cached expansion is usable only while it still covers the current list row. */
export function nativeThreadCacheMatchesRow(
  row: NativeThreadMember & { message_count?: unknown },
  cached: readonly NativeThreadMember[] | null | undefined,
): boolean {
  if (!Array.isArray(cached) || cached.length === 0) return false;
  const members = normalizedNativeThreadMembers(cached);
  const expected = Number(row.message_count);
  if (Number.isFinite(expected) && expected > 0 && members.length !== expected) return false;
  if (row.account_id && members.some(member => member.account_id && member.account_id !== row.account_id)) return false;
  // The representative can change after a read/filter refresh or provider move.
  // The exact physical head must still be a member.
  return members.some(member => membershipKey(member) === membershipKey(row));
}

/** Pagination only deduplicates the same physical ID within its account. */
export function missingPhysicalMessages<T extends NativeThreadMember>(existing: readonly T[], incoming: readonly T[]): T[] {
  const present = new Set(existing.map(membershipKey));
  return normalizedNativeThreadMembers(incoming).filter(row => !present.has(membershipKey(row)));
}
export function appendPhysicalMessages<T extends NativeThreadMember>(existing: T[], incoming: readonly T[]): T[] {
  const missing = missingPhysicalMessages(existing, incoming);
  return missing.length ? [...existing, ...missing] : existing;
}

import { removeGtdThreadFromSections, type GtdSections } from './gtd.ts';

/** One pending/completed GTD removal, keyed by identity + states. */
export type GtdRemovalEntry = { identity: string; states: string[]; timer: ReturnType<typeof setTimeout> };

export const pendingGtdRemovalMap = new Map<string, GtdRemovalEntry>();
export const completedGtdRemovalMap = new Map<string, GtdRemovalEntry>();

function normalizeStates(states: unknown): string[] {
  const list = Array.isArray(states) ? states : [];
  return [...new Set(list.filter((state): state is string => typeof state === 'string' && state !== ''))].sort();
}

function removalKey(identity: string, states: unknown): string {
  return JSON.stringify([identity, normalizeStates(states)]);
}

function setExpiring(map: Map<string, GtdRemovalEntry>, identity: string, states: unknown, ttlMs: number): void {
  const normalizedStates = normalizeStates(states);
  const key = removalKey(identity, normalizedStates);
  const existing = map.get(key);
  if (existing?.timer) clearTimeout(existing.timer);
  const timer = setTimeout(() => map.delete(key), ttlMs);
  map.set(key, { identity, states: normalizedStates, timer });
}

function clearRemoval(map: Map<string, GtdRemovalEntry>, identity: string, states: unknown): void {
  const key = removalKey(identity, states);
  const existing = map.get(key);
  if (existing?.timer) clearTimeout(existing.timer);
  map.delete(key);
}

export function setPendingGtdRemoval(identity: string, states: string[]): void {
  clearRemoval(completedGtdRemovalMap, identity, states);
  setExpiring(pendingGtdRemovalMap, identity, states, 30000);
}

export function setCompletedGtdRemoval(identity: string, states: string[]): void {
  clearRemoval(pendingGtdRemovalMap, identity, states);
  setExpiring(completedGtdRemovalMap, identity, states, 10000);
}

export function clearGtdRemovalGuard(identity: string, states: string[]): void {
  clearRemoval(pendingGtdRemovalMap, identity, states);
  clearRemoval(completedGtdRemovalMap, identity, states);
}

export function applyGtdRemovalGuard<S extends GtdSections>(sections: S): S {
  if (pendingGtdRemovalMap.size === 0 && completedGtdRemovalMap.size === 0) return sections;
  let guarded = sections;
  for (const removal of [...pendingGtdRemovalMap.values(), ...completedGtdRemovalMap.values()]) {
    guarded = removeGtdThreadFromSections(guarded, removal.identity, removal.states);
  }
  return guarded;
}

import type { StoreMessageRow } from '../store/index.ts';

export interface MailListSnapshot { messages: StoreMessageRow[]; total: number }
type Params = Record<string, string | number | boolean | null | undefined>;
type Ticket = { key: string; epoch: number; revision: number; request: number; accountId: string | null };

/** Bounded, memory-only first-page snapshots. They are never a substitute for revalidation. */
export function createMailListCache({ maxEntries = 8, maxRows = 1000, maxAgeMs = 300_000, now = Date.now } = {}) {
  const entries = new Map<string, { value: MailListSnapshot; at: number; accountId: string | null }>();
  const latest = new Map<string, { request: number; accountId: string | null }>();
  let epoch = -1;
  let revision = 0;
  let sequence = 0;
  let rowCount = 0;
  const remove = (key: string) => {
    const entry = entries.get(key);
    if (entry) rowCount -= entry.value.messages.length;
    entries.delete(key);
  };
  const clear = () => {
    revision += 1;
    entries.clear(); latest.clear(); rowCount = 0;
  };
  const enter = (nextEpoch: number) => {
    if (epoch !== nextEpoch) { clear(); epoch = nextEpoch; }
  };
  const keyFor = (params: Params) => JSON.stringify(Object.entries(params)
    .filter(([, value]) => value !== undefined && value !== null).sort(([a], [b]) => a.localeCompare(b)));
  return {
    clear,
    invalidate(scope?: string | readonly string[]) {
      if (scope === undefined) { clear(); return; }
      const affected = new Set(typeof scope === 'string' ? [scope] : scope);
      const matches = (accountId: string | null) => !accountId || affected.has(accountId);
      for (const [key, entry] of entries) if (matches(entry.accountId)) remove(key);
      // Evict matching in-flight tickets too. Unrelated revalidations can still
      // populate their own snapshots; unified requests always intersect a change.
      for (const [key, entry] of latest) if (matches(entry.accountId)) latest.delete(key);
    },
    get(params: Params, authEpoch: number): MailListSnapshot | undefined {
      enter(authEpoch);
      const key = keyFor(params);
      const entry = entries.get(key);
      if (!entry) return undefined;
      const age = now() - entry.at;
      if (age < 0 || age >= maxAgeMs) { remove(key); return undefined; }
      entries.delete(key); entries.set(key, entry);
      return entry.value;
    },
    begin(params: Params, authEpoch: number): Ticket | undefined {
      enter(authEpoch);
      // Long infinite-scroll windows and offset pages should not evict all of
      // the useful navigation snapshots or retain an unbounded mailbox history.
      if (Number(params.offset || 0) !== 0 || Number(params.limit || 50) > 500) return undefined;
      const key = keyFor(params);
      const request = ++sequence;
      const accountId = typeof params.accountId === 'string' ? params.accountId : null;
      latest.set(key, { request, accountId });
      return { key, epoch, revision, request, accountId };
    },
    finish(ticket: Ticket | undefined, value?: MailListSnapshot): void {
      if (!ticket || ticket.epoch !== epoch || ticket.revision !== revision || latest.get(ticket.key)?.request !== ticket.request) return;
      latest.delete(ticket.key);
      if (!value || value.messages.length > maxRows) return;
      remove(ticket.key);
      entries.set(ticket.key, { value, at: now(), accountId: ticket.accountId });
      rowCount += value.messages.length;
      while (entries.size > maxEntries || rowCount > maxRows) {
        const oldest = entries.keys().next().value;
        if (oldest === undefined) break;
        remove(oldest);
      }
    },
  };
}

export const mailListCache = createMailListCache();
export const invalidateMailListCache = (accountId?: string): void => invalidateMailListCacheForAccounts(accountId === undefined ? undefined : [accountId]);


/** Scope must cover every target. Missing/invalid hints retain the safe global fallback. */
export function invalidateMailListCacheForAccounts(accountIds?: readonly unknown[]): void {
  if (!accountIds?.length || !accountIds.every((id): id is string => typeof id === 'string' && id.length > 0 && id === id.trim())) {
    mailListCache.invalidate();
    return;
  }
  mailListCache.invalidate(accountIds);
}

import { clearReadGuards } from './pendingReads.ts';
import { getAuthEpoch, onAuthEpochChange } from './authEpoch.ts';
import { mailMutationFailure, mailMutationStatus, type MailMutationStatus } from './mailMutationOutcome.ts';

type Field = 'is_read' | 'is_starred';
type Intent = { version: number; value: boolean; status: MailMutationStatus | 'inflight' | 'reconciled'; epoch: number; observedAt?: number; settledAt?: number; previous?: Intent };
type Row = { id: string; physical_is_read?: boolean; is_read?: boolean; is_starred?: boolean; message_count?: unknown; unread_count?: unknown; category?: unknown; is_archived?: unknown; folder_paths?: unknown; _mailProjectionScope?: unknown; _mailReadbackSequence?: unknown };
type ReadbackTicket = { sequence: number; versions: Map<string, number> };
const intents = new Map<string, Intent>();
let sequence = 0;
let readbackSequence = 0;
const key = (id: string, field: Field) => `${field}:${id}`;
onAuthEpochChange(() => intents.clear());

export function beginMailFlagIntent(id: string, field: Field, value: boolean) {
  const intent: Intent = { version: ++sequence, value, status: 'inflight', epoch: getAuthEpoch(), previous: intents.get(key(id, field)) };
  intents.set(key(id, field), intent);
  return intent.version;
}
export function settleMailFlagIntent(id: string, field: Field, version: number, response: unknown, error = false) {
  const entryKey = key(id, field);
  let intent = intents.get(entryKey);
  while (intent && intent.version !== version) intent = intent.previous;
  if (!intent) return;
  intent.status = error ? mailMutationFailure(response) : mailMutationStatus(response, id);
  intent.settledAt = readbackSequence;
  let current = intents.get(entryKey);
  while (current?.status === 'failed') current = current.previous;
  if (current) intents.set(entryKey, current);
  else intents.delete(entryKey);
}
export function pendingMailFlag(id: string, field: Field) {
  const intent = intents.get(key(id, field));
  return intent && (intent.status === 'inflight' || intent.status === 'pending') ? intent.value : undefined;
}
export function mailFlagReadbackTicket(): ReadbackTicket {
  return { sequence: ++readbackSequence, versions: new Map([...intents]
    .filter(([, value]) => value.status !== 'inflight').map(([id, value]) => [id, value.version])) };
}

/** A later authoritative GET acknowledges a physical flag; older GETs stay fenced. */
export function projectMailFlagIntents<T extends Row>(rows: readonly T[], ticket?: ReadbackTicket): T[] {
  return rows.map(row => {
    let result = row;
    for (const field of ['is_read', 'is_starred'] as const) {
      const id = key(row.id, field);
      const intent = intents.get(id);
      if (!intent) continue;
      const threadRow = Number(row.message_count) > 1;
      // A thread head's aggregate is not the representative copy's own read flag.
      const observed = field === 'is_read' && threadRow ? row.physical_is_read : row[field];
      if (intent.status === 'reconciled') {
        if (!ticket) continue;
        if (ticket.sequence > (intent.observedAt ?? 0) && typeof observed === 'boolean') {
          intent.value = observed;
          intent.observedAt = ticket.sequence;
          continue;
        }
      } else if (ticket?.versions.get(id) === intent.version && typeof observed === 'boolean') {
        // A GET begun after settlement is authoritative even when an uncertain
        // write did not land. Waiting for equality would hide unread mail forever.
        intent.value = observed;
        intent.status = 'reconciled';
        intent.observedAt = ticket.sequence;
        intent.previous = undefined;
        if (field === 'is_read') clearReadGuards(row.id);
        continue;
      }
      if (threadRow && field === 'is_read') {
        result = { ...result, physical_is_read: intent.value };
      } else {
        result = { ...result, [field]: intent.value,
          ...(field === 'is_read' && row.unread_count !== undefined ? { unread_count: intent.value ? 0 : 1 } : {}) };
      }
    }
    return result;
  });
}

type ScopedRow = Row & { account_id?: string; folder?: string };
export function isInboxPhysicalMessage(row: { folder?: unknown; folder_paths?: unknown; is_archived?: unknown }): boolean {
  return row.is_archived !== true && (row.folder === 'INBOX'
    || (Array.isArray(row.folder_paths) && row.folder_paths.includes('INBOX')));
}
export function scopedThreadUnreadCount(row: ScopedRow, children: readonly ScopedRow[]): number {
  const scope = row._mailProjectionScope && typeof row._mailProjectionScope === 'object'
    ? row._mailProjectionScope as { folder?: string; category?: string } : { folder: row.folder };
  return children.filter(child => {
    if (child.account_id !== row.account_id || child.is_read) return false;
    const folder = scope.folder;
    if (folder === 'Archive') {
      if (child.folder !== folder && child.is_archived !== true) return false;
    } else if (folder) {
      if (child.is_archived === true) return false;
      if (child.folder !== folder && !(Array.isArray(child.folder_paths) && child.folder_paths.includes(folder))) return false;
    }
    return !scope.category || (scope.category === 'primary'
      ? !child.category || child.category === 'primary' : child.category === scope.category);
  }).length;
}

/** Keep cached complete thread aggregates stable while individual copies are pending. */
export function projectMailThreadRows<T extends Row & { thread_id?: string; account_id?: string; folder?: string }>(rows: T[], cache: Record<string, readonly ScopedRow[]>): T[] {
  return projectMailFlagIntents(rows).map(row => {
    if (!(Number(row.message_count) > 1)) return row;
    const children = cache[row.thread_id || row.id];
    if (!children || children.length !== Number(row.message_count) || !children.some(child => child.id === row.id)) return row;
    const active = (field: Field) => children.some(child => {
      const intent = intents.get(key(child.id, field));
      if (!intent) return false;
      if (intent.status === 'inflight') return true;
      // A list started after settlement already contains the current aggregate.
      // Its unread child may not be the representative, so retaining that child's
      // cached optimism would hide unread mail despite a successful readback.
      if (typeof row._mailReadbackSequence === 'number') {
        const observedAfter = intent.status === 'reconciled' ? intent.observedAt : intent.settledAt;
        return row._mailReadbackSequence <= (observedAfter ?? 0);
      }
      return intent.status !== 'reconciled';
    });
    if (!active('is_read') && !active('is_starred')) return row;
    const projected = projectMailFlagIntents(children);
    const unread = scopedThreadUnreadCount(row, projected);
    return { ...row,
      ...(active('is_read') ? { unread_count: unread, is_read: unread === 0, physical_is_read: projected.find(child => child.id === row.id)?.is_read } : {}),
      ...(active('is_starred') ? { is_starred: projected.some(child => child.is_starred) } : {}),
    };
  });
}
