export function clampRightSidebarWidth(value: unknown, { min = 200, max = 600, fallback = 296 } = {}) {
  if (value == null || value === '') return fallback;
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.round(Math.min(max, Math.max(min, n)));
}

/**
 * Process-wide authentication generation for work that must outlive a component.
 * This module deliberately has no store/API imports, so the API client can use it
 * without creating an api → store import cycle.
 */
let authEpoch = 0;
const listeners = new Set<(epoch: number) => void>();

export function getAuthEpoch(): number {
  return authEpoch;
}

export function isCurrentAuthEpoch(epoch: number): boolean {
  return authEpoch === epoch;
}

export function setAuthEpoch(nextEpoch: number): void {
  if (nextEpoch === authEpoch) return;
  authEpoch = nextEpoch;
  for (const listener of listeners) listener(authEpoch);
}

export function onAuthEpochChange(listener: (epoch: number) => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

// Keep client-side navigation state pointing only at accounts that still exist.
//
// selectedAccountId is restored from localStorage at startup and was never checked against
// the account list. Deleting the account you had selected therefore left the client pinned to
// an id the server no longer knows, and localStorage made it survive reloads. The symptoms
// looked unrelated to each other and none of them named the cause: the mailbox rendered empty,
// every folder poll for the dead account returned 404 on a 60s loop, and the favicon badge read
// `byAccount[selectedAccountId] ?? 0`, so it showed nothing while other accounts genuinely had
// unread mail.
//
// Both helpers return the input unchanged when they cannot improve on it, including the same
// object reference for folders, so a no-op cannot trigger a re-render.

type AccountWithId = { id: string };

function hasAccountId(value: unknown): value is AccountWithId {
  return typeof value === 'object' && value !== null && 'id' in value && typeof value.id === 'string';
}

function liveAccountIds(accounts: unknown): Set<string> | null {
  if (!Array.isArray(accounts)) return null;

  const ids = new Set<string>();
  const entries: unknown[] = accounts;
  for (const account of entries) {
    if (hasAccountId(account)) ids.add(account.id);
  }
  return ids;
}

/**
 * The account that should be selected, given the accounts that actually exist.
 * Returns null for the unified inbox, which is the right fallback: it is always valid.
 */
export function resolveSelectedAccount(accounts: unknown, selectedAccountId: string | null | undefined): string | null {
  if (!selectedAccountId) return null;                    // already the unified inbox
  const live = liveAccountIds(accounts);
  if (live === null) return selectedAccountId;            // list unknown, do not guess
  return live.has(selectedAccountId) ? selectedAccountId : null;
}

/** Drop cached folder lists belonging to accounts that no longer exist. */
export function pruneFolders<Value, Folders extends Record<string, Value> | null>(folders: Folders, accounts: unknown) {
  const live = liveAccountIds(accounts);
  if (!folders || live === null) return folders;

  const entries = Object.entries(folders);
  const kept = entries.filter(([id]) => live.has(id));
  if (kept.length === entries.length) return folders;     // unchanged: preserve identity
  return Object.fromEntries(kept);
}

/** A message row as the archive view sees it. */
export interface ArchiveMessage {
  id?: string;
  thread_id?: string;
  account_id?: string;
  folder?: string;
  is_read?: boolean;
  [key: string]: unknown;
}

/** The view-defining state the archive cache key is computed from. */
export interface ArchiveViewKeyInput {
  selectedAccountId?: string | null;
  selectedFolder?: string | null;
  searchQuery?: string | null;
  threadedView?: boolean;
  unreadOnly?: boolean;
  activeCategory?: string | null;
  currentPage?: number;
  searchAllFolders?: boolean;
  activeGtdTab?: string | null;
  pageSize?: number;
  scrollMode?: string | null;
  categorizationEnabled?: boolean;
  accountCategorizationEnabled?: boolean;
  unifiedInboxAccountKey?: string | null;
  showGtdTab?: boolean;
}

/** One visible row plus the physical copies a bulk archive will act on. */
export interface ArchiveTargetGroup<T extends ArchiveMessage = ArchiveMessage> {
  row: T;
  targets: ArchiveMessage[];
}

/** The archive endpoint's response for one chunk of ids. */
export interface ArchiveChunkResponse {
  archived?: string[];
  noArchiveFolder?: string[];
}

/** The merged result of archiving every chunk. */
export interface ArchiveChunksResult {
  archived: string[];
  noArchiveFolder: string[];
  unconfirmed: string[];
  error: unknown;
}

export function findVisibleArchiveMessage(messages: ArchiveMessage[] | null | undefined, selectedMessageId: string | null | undefined, threadMessages: Record<string, ArchiveMessage[]> = {}): ArchiveMessage | null {
  if (!selectedMessageId || !Array.isArray(messages)) return null;
  const direct = messages.find(message => message?.id === selectedMessageId);
  if (direct) return direct;

  return messages.find((message) => {
    const threadId = message?.thread_id || message?.id;
    if (!threadId) return false;
    const children = threadMessages[threadId];
    return Array.isArray(children) && children.some(child => child?.id === selectedMessageId);
  }) || null;
}

export function archiveViewKey({
  selectedAccountId,
  selectedFolder,
  searchQuery,
  threadedView,
  unreadOnly,
  activeCategory,
  currentPage,
  searchAllFolders,
  activeGtdTab,
  pageSize,
  scrollMode,
  categorizationEnabled,
  accountCategorizationEnabled,
  unifiedInboxAccountKey,
  showGtdTab,
}: ArchiveViewKeyInput): string {
  return JSON.stringify([
    selectedAccountId ?? null,
    selectedFolder ?? null,
    String(searchQuery || '').trim(),
    Boolean(threadedView),
    Boolean(unreadOnly),
    activeCategory ?? null,
    Number(currentPage) || 1,
    Boolean(searchAllFolders),
    activeGtdTab ?? null,
    Number(pageSize) || null,
    scrollMode ?? null,
    Boolean(categorizationEnabled),
    Boolean(accountCategorizationEnabled),
    unifiedInboxAccountKey ?? null,
    Boolean(showGtdTab),
  ]);
}

export function archiveTargetsForFolder<T extends ArchiveMessage, R extends ArchiveMessage>(
  message: T | null | undefined,
  resolvedMessages: readonly R[] | null | undefined,
  folder: string | null | undefined,
  isThreadRow: boolean,
  accountId: string | null = null,
): Array<T | R> {
  if (!message) return [];
  if (!isThreadRow) return [message];

  const seen = new Set<string>();
  const targets = (Array.isArray(resolvedMessages) ? resolvedMessages : []).filter((candidate) => {
    if (!candidate?.id || candidate.folder !== folder || seen.has(candidate.id)) return false;
    if (accountId && candidate.account_id !== accountId) return false;
    seen.add(candidate.id);
    return true;
  });
  if (
    message.id
    && message.folder === folder
    && (!accountId || message.account_id === accountId)
    && !seen.has(message.id)
  ) {
    targets.push(message);
  }
  return targets.length > 0 ? targets : [message];
}

export async function archiveTargetGroupsForRows<T extends ArchiveMessage>(
  messages: readonly T[] | null | undefined,
  resolveMessages: (message: T) => readonly ArchiveMessage[] | Promise<readonly ArchiveMessage[]>,
  folder: string | null | undefined,
  isThreadRow: (message: T) => boolean,
  accountId: string | null = null,
  concurrency = 8,
): Promise<Array<ArchiveTargetGroup<T>>> {
  const rows = Array.isArray(messages) ? messages : [];
  const groups: Array<ArchiveTargetGroup<T>> = [];
  for (let offset = 0; offset < rows.length; offset += concurrency) {
    const batch = await Promise.all(rows.slice(offset, offset + concurrency).map(async (row) => {
      const resolved = await resolveMessages(row);
      return {
        row,
        targets: archiveTargetsForFolder(row, resolved, folder, isThreadRow(row), accountId),
      };
    }));
    groups.push(...batch);
  }
  return groups;
}

export async function archiveInChunks(
  ids: string[],
  archive: (ids: string[]) => Promise<ArchiveChunkResponse>,
  chunkSize = 500,
): Promise<ArchiveChunksResult> {
  const archived: string[] = [];
  const noArchiveFolder: string[] = [];
  for (let offset = 0; offset < ids.length; offset += chunkSize) {
    try {
      const result = await archive(ids.slice(offset, offset + chunkSize));
      archived.push(...(result.archived || []));
      noArchiveFolder.push(...(result.noArchiveFolder || []));
    } catch (error) {
      return { archived, noArchiveFolder, unconfirmed: ids.slice(offset), error };
    }
  }
  return { archived, noArchiveFolder, unconfirmed: [], error: null };
}

export function unreadCountsByAccount(messages: ArchiveMessage[] | null | undefined): Map<string, number> {
  const counts = new Map<string, number>();
  for (const message of Array.isArray(messages) ? messages : []) {
    if (!message?.account_id || message.is_read) continue;
    counts.set(message.account_id, (counts.get(message.account_id) || 0) + 1);
  }
  return counts;
}

export function currentThreadLoadVersion(versions: Map<string, number>, threadId: string): number {
  return versions.get(threadId) || 0;
}

export function invalidateThreadLoad(versions: Map<string, number>, threadId: string): number {
  const next = currentThreadLoadVersion(versions, threadId) + 1;
  versions.set(threadId, next);
  return next;
}

export function isCurrentThreadLoad(versions: Map<string, number>, threadId: string, version: number): boolean {
  return currentThreadLoadVersion(versions, threadId) === version;
}

export function removeThreadCacheEntry<T>(cache: Record<string, T[]> | null | undefined, threadId: string): Record<string, T[]> {
  const next = { ...(cache || {}) };
  delete next[threadId];
  return next;
}

export const DEFAULT_CALENDAR_PREFERENCES = Object.freeze({
  calendarWorkDays: Object.freeze([1, 2, 3, 4, 5]),
  calendarWorkHoursStart: '09:00',
  calendarWorkHoursEnd: '17:00',
});

export const CALENDAR_VIEWS = Object.freeze(['month', 'week', 'workweek', 'agenda']);
export const CALENDAR_VIEW_DEFAULT = 'month';
// The view is remembered per device (like the panel widths), not per account: how
// much of a calendar fits on screen is a property of the screen. A phone and a
// desktop can therefore keep different views without fighting each other.
export const CALENDAR_VIEW_STORAGE_KEY = 'mailflow_calendar_view';

export function normalizeCalendarView(value: unknown) {
  return typeof value === 'string' && CALENDAR_VIEWS.includes(value) ? value : CALENDAR_VIEW_DEFAULT;
}

export function readStoredCalendarView() {
  try {
    return normalizeCalendarView(localStorage.getItem(CALENDAR_VIEW_STORAGE_KEY));
  } catch {
    // A blocked storage must not stop the calendar from opening.
    return CALENDAR_VIEW_DEFAULT;
  }
}

export function storeCalendarView(value: unknown) {
  const view = normalizeCalendarView(value);
  try {
    localStorage.setItem(CALENDAR_VIEW_STORAGE_KEY, view);
  } catch { /* a blocked storage must not break switching the view */ }
  return view;
}

export function normalizeCalendarWorkDays(value: unknown) {
  if (!Array.isArray(value)) return [...DEFAULT_CALENDAR_PREFERENCES.calendarWorkDays];
  const days = [...new Set(value.filter((day: unknown): day is number => typeof day === 'number' && Number.isInteger(day) && day >= 0 && day <= 6))].sort((a, b) => a - b);
  return days.length ? days : [...DEFAULT_CALENDAR_PREFERENCES.calendarWorkDays];
}

export function normalizeCalendarWorkTime(value: unknown, fallback: string = '09:00') {
  if (typeof value !== 'string' || !/^([01]\d|2[0-3]):[0-5]\d$/.test(value)) return fallback;
  return value;
}

