// Untyped lookup view of FONT_SETS: callers may hold an arbitrary saved key, and the
// runtime already falls back to FONT_SETS.default for unknown keys.
const FONT_SETS_BY_KEY: Record<string, (typeof FONT_SETS)[keyof typeof FONT_SETS]> = FONT_SETS;

// Fonts are self-hosted and declared up front in public/fonts/fonts.css (loaded from
// index.html), so there is nothing to fetch at runtime. Kept as an exported no-op
// because AdminPanel still imports it. A declared @font-face never downloads until the
// active font-family references it, so switching sets costs no network request.
export function loadFontSet(_fontKey?: string): void {
  // Intentionally empty: the @font-face rules are always present and the browser
  // lazy-loads only the active set, so there is nothing to do at runtime.
}

// Apply a font set: update the CSS custom properties. The self-hosted @font-face rules
// are already present, so the browser lazy-loads only the active set's files.
export function applyFontSet(fontKey: string) {
  if (typeof document === 'undefined') return; // no-op without a DOM (SSR / tests)
  const set = FONT_SETS_BY_KEY[fontKey] || FONT_SETS.default;
  const root = document.documentElement;
  for (const [key, value] of Object.entries(set.vars)) {
    root.style.setProperty(key, String(value));
  }
}

// Font size scaling is applied reactively in MailApp via the store's fontSize
// value using CSS transform, so no root-level changes are needed here.
export function applyFontSize(_pct?: number): void {
  // Intentionally empty: scaling is applied reactively by MailApp from the store's
  // fontSize value. The parameter mirrors applyFontSet at the call sites.
}

// Retro themes ship with a period-correct font: selecting the theme auto-applies the
// matching font set. Any theme not listed here uses the user's chosen font.
export const THEME_FONT = { winxp: 'winxp', win9x: 'win9x' };

// Retro fonts are theme-bound — they're applied automatically by their theme and must NOT
// be selectable as standalone choices in the font picker, or they'd become the user's saved
// font and "stick" after switching back to a normal theme.
const RETRO_FONTS = new Set(Object.values(THEME_FONT));
export function isRetroFont(key: string) { return RETRO_FONTS.has(key); }

// The font that should actually render for a given theme: the paired retro font when the
// theme has one, otherwise the user's saved choice — but never a retro font under a normal
// theme (that's the "font won't change back" bug), so fall back to the default in that case.
export function effectiveFontSet(theme: string, savedFont: string) {
  if (Object.hasOwn(THEME_FONT, theme)) return THEME_FONT[theme as keyof typeof THEME_FONT];
  return isRetroFont(savedFont) ? 'default' : (savedFont || 'default');
}

/** Whether a value is a theme that overrides the font (THEME_FONT is looked up dynamically). */
export function isThemeFont(name: unknown): name is keyof typeof THEME_FONT {
  return typeof name === 'string' && Object.hasOwn(THEME_FONT, name);
}

import { clampPanelWidth, PANEL_WIDTH_DEFAULT } from './utils/panelWidth.ts';
import type { TFunction } from 'i18next';

// Each layout defines the structural arrangement of the three-pane mail UI.
// direction: 'row' = list beside reading pane; 'column' = list above reading pane
// listWidth: px width of the message list in row mode (null for column mode)
// rowPy / rowPx: vertical / horizontal padding inside each message row

export const LAYOUTS = {
  focused: {
    label: 'Focused',
    description: 'Minimal list panel, maximum reading area',
    direction: 'row',
    listWidth: 210,
    rowPy: 8,
    rowPx: 10,
  },

  compact: {
    label: 'Compact',
    description: 'Dense rows — fit more messages at once',
    direction: 'row',
    listWidth: 300,
    rowPy: 7,
    rowPx: 12,
  },

  comfortable: {
    label: 'Comfortable',
    description: 'Spacious rows with generous padding for easy scanning',
    direction: 'row',
    listWidth: 360,
    rowPy: 16,
    rowPx: 16,
  },

  wide: {
    label: 'Wide',
    description: 'Broad list shows longer subjects and previews',
    direction: 'row',
    listWidth: 560,
    rowPy: 13,
    rowPx: 16,
  },

  vertical: {
    label: 'Vertical Split',
    description: 'Message list stacked above the reading pane',
    direction: 'column',
    listWidth: null,
    rowPy: 9,
    rowPx: 14,
  },
};

export const DEFAULT_LAYOUT = 'comfortable';

export type LayoutKey = keyof typeof LAYOUTS;

/** True when a persisted or synced value names a currently-supported preset. */
function isLayoutKey(value: unknown): value is LayoutKey {
  return typeof value === 'string' && value in LAYOUTS;
}

// Coerce a layout key to a known preset, falling back to the default. Guards
// against stale or removed presets persisted in localStorage or synced from the
// server — an unknown key (e.g. an old "classic" preset) must never reach a
// consumer, since it used to crash the message list (#207).
export function normalizeLayout(layoutKey: unknown): LayoutKey {
  return isLayoutKey(layoutKey) ? layoutKey : DEFAULT_LAYOUT;
}

// customListWidth: optional px override from drag-to-resize (persisted in localStorage).
// When provided it is applied instead of the preset listWidth.
// The width is shared by every list-style panel (mail, contacts, calendar), so the
// same override also drives the contact list and the calendar rail/agenda.
export function applyLayout(layoutKey: string, customListWidth: number | undefined = undefined): void {
  const layout = LAYOUTS[normalizeLayout(layoutKey)];
  const root = document.documentElement;
  root.style.setProperty('--layout-row-py', layout.rowPy + 'px');
  root.style.setProperty('--layout-row-px', layout.rowPx + 'px');
  // The stacked (column) preset has no list width of its own, but Contacts and
  // Calendar still read the shared column width, so it must always be defined.
  const width = clampPanelWidth(customListWidth) ?? layout.listWidth ?? PANEL_WIDTH_DEFAULT;
  root.style.setProperty('--list-width', width + 'px');
}

// Labels are resolved at render time so changing the language updates open menus.
export function localizedLayout(key: string, t: TFunction): { label: string; description: string } {
  const labels: Record<string, () => [string, string]> = {
    focused: () => [t('layouts.focused.label'), t('layouts.focused.description')],
    compact: () => [t('layouts.compact.label'), t('layouts.compact.description')],
    comfortable: () => [t('layouts.comfortable.label'), t('layouts.comfortable.description')],
    wide: () => [t('layouts.wide.label'), t('layouts.wide.description')],
    vertical: () => [t('layouts.vertical.label'), t('layouts.vertical.description')],
  };
  const [label, description] = (labels[key] || labels.comfortable)();
  return { label, description };
}

import { mailFlagReadbackTicket, projectMailFlagIntents } from './mailFlagIntents.ts';
import { mailListCache, invalidateMailListCacheForAccounts, type MailListSnapshot } from './mailListCache.ts';
import type { StoreMessageRow } from '../store/index.ts';
import type { GtdFolderMap } from './gtd.ts';
import { getAuthEpoch, isCurrentAuthEpoch } from './authEpoch.ts';

const BASE = '/api';

// Sent on every /api request so the backend CSRF guard accepts it. A cross-site
// form/navigation cannot set a custom header, and a cross-origin fetch that tries
// triggers a CORS preflight the server rejects. Any raw fetch() to /api elsewhere
// in the app must include this same header (see CSRF_HEADER).
export const CSRF_HEADER = 'X-Requested-With';
export const CSRF_VALUE = 'MailFlow';
const messageBodyRequests = new Map();

export interface CollectionDeletionResponse {
  state: 'confirmed' | 'pending' | 'retryable' | 'outcome_unknown' | 'conflict' | 'failed';
  operationId?: string;
  code?: string;
}

/** An empty or malformed remote response cannot confirm provider absence. */
export function normalizeCollectionDeletionResponse(value: unknown): CollectionDeletionResponse {
  if (!value || typeof value !== 'object') return { state: 'outcome_unknown' };
  const row = value as Record<string, unknown>;
  const state = row.state;
  return {
    state: state === 'confirmed' || state === 'pending' || state === 'retryable' || state === 'conflict' || state === 'failed' ? state : 'outcome_unknown',
    ...(typeof row.operationId === 'string' ? { operationId: row.operationId } : {}),
    ...(typeof row.code === 'string' ? { code: row.code } : {}),
  };
}

/** Query-string parameters as callers pass them. */
/** A folder as GET /accounts/:id/folders returns it. */
export interface FolderListEntry {
  path: string;
  name?: string;
  special_use?: string | null;
  delimiter?: string | null;
  [key: string]: unknown;
}

/** A calendar event payload (updateEvent reads recurrenceId to target an occurrence). */
export interface CalendarEventPayload {
  recurrenceId?: string | null;
  [key: string]: unknown;
}

export type QueryParams = Record<string, string | number | boolean | null | undefined>;

export interface ThreadResponse {
  messages: StoreMessageRow[];
}

/** Serialise query parameters, dropping absent values. */
export function toSearchParams(params: QueryParams): string {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== null) search.set(key, String(value));
  }
  return search.toString();
}

async function request(method: string, path: string, body: unknown = undefined, extraHeaders: Record<string, string> | undefined = undefined, extraOptions: RequestInit = {}, mailCacheAccountIds?: readonly unknown[]) {
  // Capture before either cache fence, so a late write cannot invalidate a
  // newer session. Keep the scope stable until the write settles.
  const requestAuthEpoch = getAuthEpoch();
  const affectsMailCache = method !== 'GET' && path.startsWith('/mail/') && !path.endsWith('/body-access');
  const cacheScope = mailCacheAccountIds ? [...mailCacheAccountIds] : undefined;
  if (affectsMailCache) invalidateMailListCacheForAccounts(cacheScope);
  try {
    const headers: Record<string, string> = { [CSRF_HEADER]: CSRF_VALUE, ...(extraHeaders || {}) };
    if (body) headers['Content-Type'] = 'application/json';
    const opts: RequestInit = {
      method,
      credentials: 'include',
      headers,
      ...extraOptions,
    };
    if (body) opts.body = JSON.stringify(body);
    const res = await fetch(BASE + path, opts);
    if (!res.ok) {
      if (res.status === 423 && isCurrentAuthEpoch(requestAuthEpoch)) {
        // Server-enforced screen lock (#235) — surface the lock overlay from current-session calls only.
        window.dispatchEvent(new CustomEvent('inboxora:locked'));
      }
      if (res.status === 401 && !path.startsWith('/auth/') && isCurrentAuthEpoch(requestAuthEpoch)) {
        window.dispatchEvent(new CustomEvent('inboxora:session_expired'));
      }
      const err: unknown = await res.json().catch(() => ({ error: 'Request failed' }));
      const payload = typeof err === 'object' && err !== null ? err as Record<string, unknown> : {};
      // Routes may include structured `details`, but Error.message must always be safe, short text — never
      // JavaScript's "[object Object]" fallback.
      const message = typeof payload.error === 'string' ? payload.error
        : typeof payload.message === 'string' ? payload.message : 'Request failed';
      const error = new Error(message);
      error.status = res.status;
      // The domain code, so a caller can answer in the user's own language rather than matching the server's prose.
      if (typeof payload.code === 'string') (error as Error & { code?: string }).code = payload.code;
      // Source context is a stable, server-whitelisted diagnostic value. It can be
      // a short scope string or a persisted calendar-source descriptor; retain it
      // without coercing structured context to an unusable message.
      if (payload.source !== undefined) (error as unknown as Record<string, unknown>).source = payload.source;
      if (payload.sync !== undefined) (error as unknown as Record<string, unknown>).sync = payload.sync;
      if (payload.details) (error as Error & { details?: unknown }).details = payload.details;
      throw error;
    }
    // A successful DELETE may deliberately return no representation (HTTP 204).
    if (res.status === 204) return null;
    return await res.json();
  } finally {
    // An overlapping GET may contain pre-commit data. Fence entries and tickets
    // on success and failure: a network failure need not mean nothing changed.
    if (affectsMailCache && isCurrentAuthEpoch(requestAuthEpoch)) invalidateMailListCacheForAccounts(cacheScope);
  }
}

// Aborting a request rejects with a DOMException named AbortError (or, in some
// runtimes, an object carrying that name). Callers use this to tell a deliberate
// cancellation from a real failure, so a cancelled load never surfaces an error.
export function isAbortError(error: unknown): boolean {
  if (typeof error !== 'object' || error === null) return false;
  if ('name' in error && error.name === 'AbortError') return true;
  if ('code' in error && error.code === 20) return true;
  return false;
}

export async function streamAiChat(messages: unknown[], { signal, onDelta }: { signal?: AbortSignal; onDelta?: (fullText: string, delta: string) => void } = {}) {
  const response = await fetch(`${BASE}/ai/chat`, {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', [CSRF_HEADER]: CSRF_VALUE },
    body: JSON.stringify({ messages }),
    signal,
  });
  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'AI request failed' }));
    throw new Error(error.error || 'AI request failed');
  }
  if (!response.body) throw new Error('AI response body is unavailable');

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let fullText = '';
  let completed = false;

  function consumeLine(line: string) {
    if (!line.startsWith('data:')) return;
    const data = line.slice(5).trim();
    if (!data) return;
    if (data === '[DONE]') {
      completed = true;
      return;
    }
    try {
      const parsed = JSON.parse(data);
      if (parsed?.error) {
        const message = typeof parsed.error === 'string' ? parsed.error : parsed.error.message;
        throw new Error(message || 'AI request failed');
      }
      const delta = parsed?.choices?.[0]?.delta?.content;
      if (typeof delta === 'string' && delta) {
        fullText += delta;
        onDelta?.(fullText, delta);
      }
    } catch (error) {
      if (error instanceof SyntaxError) return;
      throw error;
    }
  }

  try {
    while (!completed) {
      const { done, value } = await reader.read();
      if (done) {
        buffer += decoder.decode();
        break;
      }
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() ?? '';
      for (const line of lines) {
        consumeLine(line);
        if (completed) break;
      }
    }
    if (!completed && buffer) consumeLine(buffer);
    if (!completed) throw new Error('AI response ended before completion');
    return fullText;
  } finally {
    await reader.cancel().catch(() => {});
  }
}

function getMessageBody(id: string, remoteImages = false, copyId: string | null = null) {
  const key = `${id}:${copyId || 'default'}:${remoteImages ? 'remote' : 'blocked'}`;
  const existing = messageBodyRequests.get(key);
  if (existing) return existing;
  const query = new URLSearchParams();
  if (remoteImages) query.set('remoteImages', '1');
  if (copyId) query.set('copyId', copyId);
  const suffix = query.toString() ? `?${query.toString()}` : '';
  const promise = request('GET', `/mail/messages/${id}/body${suffix}`)
    .finally(() => messageBodyRequests.delete(key));
  messageBodyRequests.set(key, promise);
  return promise;
}

