import { toAppError } from '../utils/errors.ts';
// Pure helpers for GTD display surfaces. Kept free of React/DOM so they can be
// unit-tested under `node --test` at their pure seams.

// A commitment older than this many days is shown with a red-tinted aging chip.
// Module constant (no "N stale" header aggregate — per-row only).
export const STALE_DAYS = 14;

// GTD state display colors (contrast-validated set). Inline-style values, not
// theme vars — five distinct per-state hues (plus the neutral someday grey)
// don't map onto the four accent/green/red/amber tokens the theme exposes.
export const GTD_COLORS = {
  todo: '#4A9EDD',
  watch: '#D9B430',
  delegated: '#E08B3D',
  someday: 'var(--text-tertiary)',
  reference: '#7157d9',
  done: '#2FBD85',
};

// Same-hue ~15% alpha backgrounds for count chips / kind chips (color recipe:
// saturated glyph/text + same-hue low-alpha chip + always a text label).
export const GTD_CHIP_BG = {
  todo: 'rgba(74,158,221,0.16)',
  watch: 'rgba(217,180,48,0.15)',
  delegated: 'rgba(224,139,61,0.15)',
  someday: 'rgba(139,139,155,0.16)',
  reference: 'rgba(113,87,217,0.16)',
  done: 'rgba(47,189,133,0.14)',
};

// GTD section display order (Waiting merges watch + delegated): Todo → Waiting →
// Reference → Someday — actionable items first, then delegated/waiting-on items,
// then reference material, then someday/maybe deferred to last.
export const GTD_DISPLAY_SECTION_ORDER = ['todo', 'waiting', 'reference', 'someday'] as const;

// The five GTD states and their default state→folder map (mirrors the backend
// gtdConfig defaults). Classify actions COPY into the resolved folder.
export const GTD_STATES: Array<keyof typeof DEFAULT_GTD_FOLDERS> = ['todo', 'watch', 'delegated', 'someday', 'reference'];
export const DEFAULT_GTD_FOLDERS = {
  todo: 'Todo', watch: 'Watch', delegated: 'Delegated', someday: 'Someday', reference: 'Reference',
};

// Merge an account's stored gtd_folders overrides over the defaults (same shape
// the backend getGtdConfig produces).
/** A state -> folder-path map as the settings form and accounts store it. */
export type GtdFolderMap = Record<string, string>;

/** The account fields the GTD helpers read. */
export type GtdAccountLike = {
  id?: string;
  gtd_enabled?: boolean;
  gtd_folders?: GtdFolderMap | null;
  [key: string]: unknown;
};

/** A section after normalisation: every field present. */
/** The display fields a GTD entry row derives from its thread. */
export interface GtdRowDisplay {
  kinds: string[];
  rowState: string;
  unread: boolean;
  days: number | null;
  stale: boolean;
  sender: string;
}

/** A section after normalisation: every field present. */
export interface GtdNormalizedSection {
  total: number;
  unread: number;
  threads: GtdThread[];
  [key: string]: unknown;
}

export interface GtdThread {
  id?: string;
  message_id?: string;
  date?: string | number | Date | null;
  is_read?: boolean;
  subject?: string | null;
  gist?: string | null;
  snippet?: string | null;
  /** Attached by the Waiting merge (a thread can carry both watch and delegated). */
  gtdKind?: string;
  gtdKinds?: string[];
  /** The conservative (older) waiting date used for the aging chip. */
  agingDate?: string | number | Date | null;
  from_name?: string | null;
  from_email?: string | null;
  [key: string]: unknown;
}

/** The minimal row shape the identity/dedupe helpers read. */
export interface GtdIdentityRow {
  id?: string;
  message_id?: string | null;
  folder?: string | null;
  date?: string | number | Date | null;
}

export interface GtdSection {
  total?: number;
  unread?: number;
  threads?: GtdThread[];
  [key: string]: unknown;
}

export type GtdSections = Record<string, GtdSection>;

export interface GtdRemovalSnapshot {
  identity: string;
  removedByState: Record<string, Array<{ index: number; thread: GtdThread }>>;
}

export function resolveAccountGtdFolders(account: GtdAccountLike | null | undefined): GtdFolderMap {
  const stored = account?.gtd_folders && typeof account.gtd_folders === 'object' && !Array.isArray(account.gtd_folders)
    ? account.gtd_folders : {};
  return { ...DEFAULT_GTD_FOLDERS, ...stored };
}

// Reduce a settings-form folder map to only the entries that differ from the
// defaults, trimmed. Stored as the account's gtd_folders so an untouched mapping
// persists as {} ("all defaults") and a later default change still propagates. A
// blank field falls back to its default (dropped here).
export function diffGtdFolders(folders: GtdFolderMap | null | undefined): GtdFolderMap {
  const out: GtdFolderMap = {};
  for (const state of GTD_STATES) {
    const v = (folders?.[state] ?? '').trim();
    if (v && v !== DEFAULT_GTD_FOLDERS[state]) out[state] = v;
  }
  return out;
}

// Detect GTD states whose resolved folder path collides with another state's.
// Mirrors the backend guard so the settings form can block a save before it hits
// the API: a blank field falls back to its default (and both sides are trimmed)
// before comparison, so two states pointing at the same folder — by override or by
// a typo onto another state's default name — are caught. Returns collision groups
// [{ folder, states }], empty when all five are distinct.
export function findGtdFolderCollisions(folders: GtdFolderMap | null | undefined): Array<{ folder: string; states: string[] }> {
  const byFolder: Record<string, string[]> = {};
  for (const state of GTD_STATES) {
    const path = (folders?.[state] ?? '').trim() || DEFAULT_GTD_FOLDERS[state];
    (byFolder[path] ||= []).push(state);
  }
  return Object.entries(byFolder)
    .filter(([, states]) => states.length > 1)
    .map(([folder, states]) => ({ folder, states }));
}

// Which GTD states a message's thread is currently labelled with, given the
// thread's folder paths and the account's resolved state→folder map. Drives the
// "Remove from <state>" context-menu options (only shown for labels present).
export function gtdStatesInFolders(folders: string[] | null | undefined, resolvedMap: GtdFolderMap): Array<(typeof GTD_STATES)[number]> {
  const set = new Set(Array.isArray(folders) ? folders : []);
  return GTD_STATES.filter(state => set.has(resolvedMap?.[state]));
}

// Whole days between a thread head's date and now. null when there is no
// parseable date. Future dates clamp to 0 (a freshly-synced head can carry a
// clock-skewed date slightly ahead of the client).
export function agingDays(dateStr: string | number | Date | null | undefined, now = Date.now()): number | null {
  if (!dateStr) return null;
  const t = new Date(dateStr).getTime();
  if (!Number.isFinite(t)) return null;
  const days = Math.floor((now - t) / (24 * 60 * 60 * 1000));
  return days < 0 ? 0 : days;
}

export function isStale(days: number | null): boolean {
  return days != null && days > STALE_DAYS;
}

export function agingLabel(days: number | null): string {
  if (days == null) return '';
  return `⏱ ${days}d`;
}

// Derive a GTD entry's display fields from its thread + section key. A merged-Waiting
// row carries gtdKinds (watch and/or delegated); everything else uses the section's own
// state for its left border and aging-pill color. The primary kind (kinds[0], watch-first)
// drives both — so a merged W+D row reads as watch (yellow), matching the Waiting section
// color. Age comes from the conservative (older) waiting date on a merged row; agingDate
// falls back to the row's own date for a single-kind row. Shared by the GTD display surfaces.
export function resolveRowDisplay(thread: GtdThread, sectionKey: string): GtdRowDisplay {
  const isWaiting = sectionKey === 'waiting';
  const kinds = isWaiting ? (thread.gtdKinds?.length ? thread.gtdKinds : [thread.gtdKind || 'watch']) : [];
  const rowState = isWaiting ? (kinds[0] || 'watch') : sectionKey;
  const unread = !thread.is_read;
  const days = agingDays(thread.agingDate ?? thread.date);
  const stale = isStale(days);
  const sender = thread.from_name || thread.from_email || '';
  return { kinds, rowState, unread, days, stale, sender };
}

// Whether GTD display surfaces apply to the current context.
// Gated first on the user having the GTD plugin activated (deactivating hides every GTD surface,
// independent of per-account config), then: unified (no account selected) → any account with GTD
// on; single account → that account's flag only. gtdActivated defaults true so callers that don't
// yet thread activation (and the unit tests) keep the pre-plugin behavior.
export function gtdActiveForContext(accounts: GtdAccountLike[] | null | undefined, selectedAccountId: string | null | undefined, gtdActivated = true): boolean {
  if (!gtdActivated) return false;
  if (!Array.isArray(accounts) || accounts.length === 0) return false;
  if (selectedAccountId == null) {
    return accounts.some(a => a?.gtd_enabled && a?.include_in_unified_inbox !== false);
  }
  const acct = accounts.find(a => a?.id === selectedAccountId);
  return !!acct?.gtd_enabled;
}

const EMPTY_SECTION = { total: 0, unread: 0, threads: [] };

function normSection(section?: GtdSection | null): GtdNormalizedSection {
  if (!section) return EMPTY_SECTION;
  return {
    total: Number(section.total) || 0,
    unread: Number(section.unread) || 0,
    threads: Array.isArray(section.threads) ? section.threads : [],
  };
}

// Thread identity for deduping the merged Waiting view. The same thread labelled
// BOTH Watch and Delegated yields two heads (one per state) that must collapse to a
// single row. message_id is preferred (stable across accounts, matching the
// backend's cross-account dedupe), then the row id — no thread_key step, to match
// the backend's analogous dedupe (gtdSections.js: message_id || id).
function waitingIdentity(t: GtdThread): string | undefined {
  return t.message_id || t.id;
}

const WAITING_KIND_ORDER = ['watch', 'delegated'];

// Merge the watch + delegated sections into one WAITING view. Heads are interleaved
// newest-first and deduped by thread identity: a thread in both folders becomes ONE
// row that carries both kinds (gtdKinds, ordered W then D), displays the newer head's
// date, and ages from the OLDER of its two waiting dates (agingDate — conservative,
// so the aging chip reflects the longest time actually waiting). Each surviving row
// also keeps a single gtdKind (its primary/first kind) for the left-border colour and
// snippet fallback.
//
// Counts: prefer the server's `waiting` rollup, which dedupes a both-labelled thread
// across the FULL watch ∪ delegated set — correct even when the overlap sits past the
// per-section head window this client holds. Only when that rollup is absent (a stale
// payload) do we fall back to deducing the dedupe from the visible heads: sum the two
// totals and subtract the collapses we can actually see, which drifts high once an
// overlap escapes the window.
export function mergeWaiting(watch?: GtdSection | null, delegated?: GtdSection | null, waiting?: GtdSection | null) {
  const w = normSection(watch);
  const d = normSection(delegated);
  const tagged = [
    ...w.threads.map(t => ({ ...t, gtdKind: 'watch' })),
    ...d.threads.map(t => ({ ...t, gtdKind: 'delegated' })),
  ].sort((a, b) => new Date(b.date || 0).getTime() - new Date(a.date || 0).getTime());

  const byId = new Map();
  const order = [];
  let dupCount = 0;        // rows collapsed onto an existing thread
  let dupUnread = 0;       // of those, how many double-counted an unread thread (both copies unread)
  for (const row of tagged) {
    const key = waitingIdentity(row);
    const existing = byId.get(key);
    if (!existing) {
      // First-seen head is the newer one (tagged is newest-first): it owns display.
      byId.set(key, { ...row, gtdKinds: [row.gtdKind], agingDate: row.date });
      order.push(key);
      continue;
    }
    dupCount += 1;
    // The per-folder unread sums count each unread copy once, so a both-labelled thread is
    // over-counted only when BOTH its copies are unread — subtract exactly then. Any single
    // unread copy already yields the correct 1 (undoing this only for the older copy dropped
    // a newer-read + older-unread thread to 0).
    if (!row.is_read && !existing.is_read) dupUnread += 1;
    if (!existing.gtdKinds.includes(row.gtdKind)) existing.gtdKinds.push(row.gtdKind);
    // Age from the earlier of the two dates.
    if (row.date && (!existing.agingDate || new Date(row.date) < new Date(existing.agingDate))) {
      existing.agingDate = row.date;
    }
  }

  const threads = order.map(key => {
    const row = byId.get(key);
    row.gtdKinds.sort((a: string, b: string) => WAITING_KIND_ORDER.indexOf(a) - WAITING_KIND_ORDER.indexOf(b));
    row.gtdKind = row.gtdKinds[0];
    return row;
  });

  const rollup = waiting && typeof waiting === 'object' ? waiting : null;
  return {
    total: rollup ? Math.max(0, Number(rollup.total) || 0) : Math.max(0, w.total + d.total - dupCount),
    unread: rollup ? Math.max(0, Number(rollup.unread) || 0) : Math.max(0, w.unread + d.unread - dupUnread),
    threads,
  };
}

// Ordered GTD display sections with Waiting merged. Each entry:
// { key, total, unread, threads }.
export function buildGtdDisplaySections(sections: GtdSections | null | undefined) {
  const s: GtdSections = sections || {};
  const waiting = mergeWaiting(s.watch, s.delegated, s.waiting);
  const byKey: Record<(typeof GTD_DISPLAY_SECTION_ORDER)[number], GtdNormalizedSection> = {
    todo: normSection(s.todo),
    waiting,
    reference: normSection(s.reference),
    someday: normSection(s.someday),
  };
  return GTD_DISPLAY_SECTION_ORDER.map(key => ({ key, ...byKey[key] }));
}

// Optimistically drop a thread's head from the given GTD state sections (after a
// done/delete/move so the GTD entry vanishes instantly; the gtd refetch reconciles the
// authoritative counts). identity is message_id||id; states are the backend section keys
// whose labels were removed (todo/watch/delegated/…). Also keeps the deduped Waiting
// rollup in step: a thread removed from watch and/or delegated adjusts sections.waiting
// ONCE (total -1; unread -1 if any removed waiting copy was unread) — because a thread in
// both folders is a single Waiting row — so the Waiting badge is correct instantly instead
// of only after the refetch. Returns the same sections reference when nothing changed, a
// new object otherwise; never mutates the input.
export function removeGtdThreadFromSections<S extends GtdSections | null | undefined>(
  sections: S,
  identity: string | null | undefined,
  states?: string[],
): S {
  if (!sections || identity == null) return sections;
  const current: GtdSections = sections;
  const next = { ...current };
  let changed = false;
  let waitingRemoved = false;   // present in watch and/or delegated → adjust rollup once
  let waitingUnread = false;    // any removed waiting copy was unread
  for (const key of states || []) {
    const sec = current[key];
    if (!sec || !Array.isArray(sec.threads)) continue;
    let removed = 0, removedUnread = 0;
    const threads = sec.threads.filter(th => {
      if ((th.message_id || th.id) !== identity) return true;
      removed += 1;
      if (!th.is_read) removedUnread += 1;
      return false;
    });
    if (!removed) continue;
    changed = true;
    if (key === 'watch' || key === 'delegated') {
      waitingRemoved = true;
      if (removedUnread) waitingUnread = true;
    }
    next[key] = {
      total: Math.max(0, (Number(sec.total) || 0) - removed),
      unread: Math.max(0, (Number(sec.unread) || 0) - removedUnread),
      threads,
    };
  }
  if (waitingRemoved && current.waiting && typeof current.waiting === 'object') {
    next.waiting = {
      ...current.waiting,
      total: Math.max(0, (Number(current.waiting.total) || 0) - 1),
      unread: Math.max(0, (Number(current.waiting.unread) || 0) - (waitingUnread ? 1 : 0)),
    };
  }
  return (changed ? next : current) as S;
}

export function snapshotGtdThreadRemoval(sections: GtdSections | null | undefined, identity: string | null | undefined, states?: string[]) {
  if (!sections || identity == null) return null;
  const removedByState: Record<string, Array<{ index: number; thread: GtdThread }>> = {};
  for (const key of [...new Set(states || [])]) {
    const sec = sections[key];
    if (!sec || !Array.isArray(sec.threads)) continue;
    const rows: Array<{ index: number; thread: GtdThread }> = [];
    sec.threads.forEach((thread, index) => {
      if ((thread.message_id || thread.id) === identity) rows.push({ index, thread });
    });
    if (rows.length) removedByState[key] = rows;
  }
  return Object.keys(removedByState).length ? { identity, removedByState } : null;
}

export function restoreGtdThreadRemoval(sections: GtdSections | null | undefined, snapshot: GtdRemovalSnapshot | null) {
  if (!sections || !snapshot) return sections;
  const next = { ...sections };
  let changed = false;
  let restoredWaiting = false;
  let restoredWaitingUnread = false;

  for (const [key, rows] of Object.entries(snapshot.removedByState)) {
    const sec = sections[key];
    if (!sec || !Array.isArray(sec.threads)) continue;
    const threads = [...sec.threads];
    let restored = 0;
    let restoredUnread = 0;
    for (const row of rows) {
      if (threads.some(thread => (thread.message_id || thread.id) === snapshot.identity)) continue;
      threads.splice(Math.min(row.index, threads.length), 0, row.thread);
      restored += 1;
      if (!row.thread.is_read) restoredUnread += 1;
    }
    if (!restored) continue;
    changed = true;
    if (key === 'watch' || key === 'delegated') {
      restoredWaiting = true;
      if (restoredUnread) restoredWaitingUnread = true;
    }
    next[key] = {
      ...sec,
      total: (Number(sec.total) || 0) + restored,
      unread: (Number(sec.unread) || 0) + restoredUnread,
      threads,
    };
  }

  if (restoredWaiting && sections.waiting && typeof sections.waiting === 'object') {
    next.waiting = {
      ...sections.waiting,
      total: (Number(sections.waiting.total) || 0) + 1,
      unread: (Number(sections.waiting.unread) || 0) + (restoredWaitingUnread ? 1 : 0),
    };
  }
  return changed ? next : sections;
}

// Optimistically flip a section thread's read flag across every state it is labelled with
// (a merged Waiting row lives in both watch and delegated), so a GTD entry's bold/normal
// styling updates instantly on a mark-read/unread; the gtd refetch reconciles. Also nudges
// the deduped Waiting rollup's unread ONCE (a row in both watch and delegated flips the
// merged unread by one, not two); the rollup total is unaffected — the thread stays in
// Waiting, only its read styling changes. Returns the same sections reference when nothing
// changed, a new object otherwise; never mutates the input.
export function setGtdThreadReadInSections(sections: GtdSections | null | undefined, identity: string | null | undefined, isRead: boolean, accountId?: string) {
  if (!sections || identity == null) return sections;
  const next = { ...sections };
  let changed = false;
  let waitingTouched = false;
  for (const [key, sec] of Object.entries(sections)) {
    if (!sec || !Array.isArray(sec.threads)) continue;
    let unreadDelta = 0, touched = false;
    const threads = sec.threads.map(th => {
      if ((th.message_id || th.id) !== identity || (accountId !== undefined && th.account_id !== accountId) || !!th.is_read === isRead) return th;
      touched = true;
      unreadDelta += isRead ? -1 : 1;
      return { ...th, is_read: isRead };
    });
    if (!touched) continue;
    changed = true;
    if (key === 'watch' || key === 'delegated') waitingTouched = true;
    next[key] = { ...sec, threads, unread: Math.max(0, (Number(sec.unread) || 0) + unreadDelta) };
  }
  if (waitingTouched && sections.waiting && typeof sections.waiting === 'object') {
    next.waiting = {
      ...sections.waiting,
      unread: Math.max(0, (Number(sections.waiting.unread) || 0) + (isRead ? -1 : 1)),
    };
  }
  return changed ? next : sections;
}

// Which message rows a GTD entry's read-toggle should act on. Section rows carry THREAD-LEVEL
// unread (a thread is unread while ANY copy is unread), which makes the two directions
// asymmetric:
//   - mark READ must reach every message in the thread: the head alone (plus the
//     server's same-message_id fan-out) misses a sibling reply that exists only in
//     INBOX, so the thread would stay unread and the refetch would revert the flip;
//   - mark UNREAD needs only the head copy — one unread copy already makes the thread
//     unread, and flipping every sibling would bold the whole thread in the inbox.
// getThread is injected (like openDeepLinkMessage) so the seam stays unit-testable.
// Degrades to the head id when the thread lookup fails or returns nothing: bulk-read
// still flips the head's copies and the gtd refetch re-shows any residual unread.
export async function collectThreadReadIds(
  thread: { id?: string; thread_key?: string },
  read: boolean,
  getThread?: (key: string) => Promise<{ messages?: Array<{ id: string }> }>,
): Promise<Array<string | undefined>> {
  if (!read || !getThread || !thread?.thread_key) return [thread.id];
  try {
    const { messages } = await getThread(thread.thread_key);
    const ids = (Array.isArray(messages) ? messages : []).map(m => m?.id).filter(Boolean);
    return ids.length ? ids : [thread.id];
  } catch {
    return [thread.id];
  }
}

export function scheduleGtdThreadAutoRead<T = ReturnType<typeof setTimeout>>(thread: GtdThread, {
  markReadBehavior,
  markReadDelay,
  readThread,
  setTimer,
}: {
  markReadBehavior?: string;
  markReadDelay?: number;
  readThread: (thread: GtdThread, isRead: boolean) => void;
  setTimer: (callback: () => void, delay: number) => T;
}) {
  if (!thread || thread.is_read || markReadBehavior === 'manual') return null;
  if (markReadBehavior === 'delay') {
    const seconds = Math.max(1, Number(markReadDelay) || 1);
    return setTimer(() => readThread(thread, true), seconds * 1000);
  }
  readThread(thread, true);
  return null;
}

export async function openGtdThreadWithAutoRead<T = ReturnType<typeof setTimeout>>(thread: GtdThread, {
  openThread,
  isCancelled,
  getPreferences,
  readThread,
  setTimer,
  publishTimer,
}: {
  openThread: () => Promise<unknown>;
  isCancelled: () => boolean;
  getPreferences: () => { markReadBehavior?: string; markReadDelay?: number };
  readThread: (thread: GtdThread, isRead: boolean) => void;
  setTimer: (callback: () => void, delay: number) => T;
  // The handle is opaque: the injected scheduler is either the real setTimeout or a
  // fake clock in tests, so callers own its concrete type.
  publishTimer: (timer: T | null) => void;
}) {
  const message = await openThread();
  if (!message || isCancelled()) return null;
  const { markReadBehavior, markReadDelay } = getPreferences();
  const timerHandle = scheduleGtdThreadAutoRead(thread, {
    markReadBehavior,
    markReadDelay,
    readThread,
    setTimer,
  });
  publishTimer(timerHandle);
  return timerHandle;
}

export function sectionBadge(count: number) {
  const n = Number(count) || 0;
  if (n <= 0) return '';
  return n > 99 ? '99+' : String(n);
}

// Whether a list row is the currently selected message. Matches across the multi-folder
// model, where one message's INBOX copy and its label-folder copy are distinct DB rows (each
// with its own id) that share an RFC message_id: so a GTD entry and the inbox row for the same
// email highlight together even though their ids differ. Prefers message_id when BOTH the row
// and the selection carry one — never matches two null/absent message_ids — and otherwise
// falls back to exact id equality, which is all a single-copy account (or a row/selection
// without a message_id) ever needs. Pure and unit-testable.
export function isSelectedRow(row: GtdIdentityRow | null | undefined, selectedId?: string | null, selectedMid?: string | null) {
  if (!row) return false;
  if (selectedMid != null && row.message_id != null && row.message_id === selectedMid) return true;
  return row.id != null && row.id === selectedId;
}

// A stable identity for a message list row: the RFC Message-ID when present, else the (volatile)
// DB row id. The row's UUID id is regenerated whenever a message is purged and re-inserted
// (folder move / resync / UID change), so deduplicating a list by id ALONE lets a reindexed
// message linger under its old id AND reappear under the new one — two rows with the same
// Message-ID, which the message-list renders as a visible duplicate (and isSelectedRow highlights
// together). Keying on the Message-ID collapses those; rows without one keep id identity so two
// distinct id-only rows never merge. Namespaced so a Message-ID can never collide with a UUID.
// Pure. Mirrors the identity rule in isSelectedRow / pickThreadMessage.
export function messageIdentity(m: GtdIdentityRow | null | undefined) {
  if (!m) return null;
  return m.message_id ? `mid:${m.message_id}` : `id:${m.id}`;
}

// Merge a freshly-fetched page of messages into an existing list, keyed by messageIdentity:
//  - an incoming row with the SAME DB id as an existing row is dropped (the existing copy may
//    carry optimistic local-only fields a network refresh lost, e.g. unread_count);
//  - an incoming row that shares a Message-ID with an existing row but carries a NEW id (the
//    message was purged+reinserted, regenerating its id) REPLACES that stale row in place, so a
//    reindexed message never shows as a duplicate and the surviving row is the fresh, clickable one;
//  - anything genuinely new is appended, de-duplicated within the incoming batch by identity.
// Returns the original array reference unchanged when nothing was added or replaced, so callers can
// skip a no-op state update. Pure.
export function appendMessagesByIdentity<T extends GtdIdentityRow>(
  existing: T[],
  incoming: readonly (T | null | undefined)[] | null | undefined,
): T[] {
  const items = (incoming || []).filter((m): m is T => !!m);
  if (items.length === 0) return existing;

  const existingIds = new Set(existing.map(m => m.id));
  const idxByMid = new Map<string, number>();
  existing.forEach((m, i) => { if (m.message_id) idxByMid.set(m.message_id, i); });

  let messages = existing;
  let mutated = false;
  const additions: T[] = [];
  const takenKeys = new Set<string | null>(); // identities already consumed from the incoming batch

  for (const m of items) {
    if (existingIds.has(m.id)) continue;   // exact same row already present — keep existing
    const key = messageIdentity(m);
    if (takenKeys.has(key)) continue;      // a same-identity incoming row was already handled
    takenKeys.add(key);
    const staleIndex = m.message_id ? idxByMid.get(m.message_id) : undefined;
    if (staleIndex !== undefined) {
      if (!mutated) { messages = existing.slice(); mutated = true; }
      messages[staleIndex] = m;              // reindexed: replace the stale row in place
    } else {
      additions.push(m);                        // genuinely new
    }
  }

  if (!mutated && additions.length === 0) return existing;
  return additions.length ? [...messages, ...additions] : messages;
}

// Collapse a message list so no two rows share a stable identity (Message-ID when present).
// The SAME email can exist as separate DB rows in more than one place the list draws from — the
// same message delivered to two accounts in a unified inbox, or a received copy alongside its
// Sent twin — and every raw list load (setMessages) would otherwise render both, even though the
// app already treats them as ONE message (see isSelectedRow, which highlights them together).
// This is the render-time guard the identity-aware merges (appendMessagesByIdentity) don't cover.
// Order-preserving; on a collision the INBOX copy wins so the list shows the received message.
// Null-safe: rows without a Message-ID key on their (unique) id, so distinct ones never merge. Pure.
export function dedupeByIdentity<T extends GtdIdentityRow>(
  list: readonly (T | null | undefined)[] | null | undefined,
): T[] {
  const idxByKey = new Map<string | null, number>(); // identity -> index in result
  const result: T[] = [];
  for (const m of list || []) {
    if (!m) continue;
    const key = messageIdentity(m);
    const seenIndex = idxByKey.get(key);
    if (seenIndex === undefined) {
      idxByKey.set(key, result.length);
      result.push(m);
    } else if (result[seenIndex].folder !== 'INBOX' && m.folder === 'INBOX') {
      result[seenIndex] = m; // prefer the INBOX copy of the same logical message
    }
  }
  return result;
}

// Filter `incoming` to the messages whose stable identity is not already present in `existing`.
// Used by restore/undo so a message the network refresh already brought back — possibly under a
// regenerated id, matched via Message-ID — is not re-added as a duplicate. Pure.
export function missingByIdentity<T extends GtdIdentityRow>(
  existing: T[],
  incoming: readonly (T | null | undefined)[] | null | undefined,
): T[] {
  const present = new Set(existing.map(m => messageIdentity(m)));
  return (incoming || []).filter((m): m is T => !!m && !present.has(messageIdentity(m)));
}

// Choose which message of a thread a deep-link should open, given the thread's rows and
// the head's RFC message_id. Prefers the row whose message_id matches — that identity is
// stable across a purge+reinsert, whereas the row PK is not — then the newest row, then
// the first. Rows without an id (nothing to open) are ignored. Pure and unit-testable.
export function pickThreadMessage<T extends GtdIdentityRow>(
  messages: readonly (T | null | undefined)[] | null | undefined,
  messageId?: string | null,
): T | null {
  const list = Array.isArray(messages) ? messages.filter((m): m is T => !!m && !!m.id) : [];
  if (list.length === 0) return null;
  const byMid = messageId && list.find(m => m.message_id === messageId);
  if (byMid) return byMid;
  return list.reduce((newest, m) =>
    (new Date(m.date || 0) >= new Date(newest.date || 0) ? m : newest), list[0]);
}

// Classify (add a state label) / unclassify (strip one) a message. Classify COPIES into
// the state's label folder; the message stays put (no optimistic removal/undo — it does
// not leave INBOX), so both just fire the API call and poke the GTD sections store to reconverge
// instead of waiting on the WS event. Deps injected (like openDeepLinkMessage) so the call
// is unit-testable; mirrors the GTD display callers' classify/remove handlers.
export async function classifyThread(id: string, state: string, {
  gtdClassify, addNotification, scheduleGtdSectionsFetch, t,
}: {
  gtdClassify: (id: string, state: string) => Promise<unknown>;
  addNotification: (n: { title?: string; body?: string }) => void;
  scheduleGtdSectionsFetch: () => void;
  t: (key: string) => string;
}) {
  try {
    await gtdClassify(id, state);
    scheduleGtdSectionsFetch();
    addNotification({ title: t('gtd.classified'), body: t(`gtd.state.${state}`) });
  } catch (err) {
    console.error('GTD classify failed:', toAppError(err).message);
    addNotification({ title: t('gtd.classifyFailed'), body: t(`gtd.state.${state}`) });
  }
}

export async function unclassifyThread(id: string, state: string, {
  gtdUnclassify, addNotification, scheduleGtdSectionsFetch, t,
}: {
  gtdUnclassify: (id: string, state: string) => Promise<unknown>;
  addNotification: (n: { title?: string; body?: string }) => void;
  scheduleGtdSectionsFetch: () => void;
  t: (key: string) => string;
}) {
  try {
    await gtdUnclassify(id, state);
    scheduleGtdSectionsFetch();
    addNotification({ title: t('gtd.removed'), body: t(`gtd.state.${state}`) });
  } catch (err) {
    console.error('GTD unclassify failed:', toAppError(err).message);
    addNotification({ title: t('gtd.removeFailed'), body: t(`gtd.state.${state}`) });
  }
}

// Monotonic click token. Each openDeepLinkMessage call claims the next value on entry
// and re-checks it before any state write; a call whose token has been superseded by a
// newer click drops its write and returns null. Because both GTD display surfaces import
// this module, the counter serialises clicks across them — the latest
// click always wins the reading pane even when a slow fetch resolves out of order.
let _deepLinkSeq = 0;

// Open an out-of-list message in the reading pane WITHOUT switching folders, using the
// deep-link stash pattern (MailApp's __dl_ threadMessages). Kept pure (deps injected) so
// the sequence is unit-testable; a naive setSelectedMessage on an out-of-list id renders a
// blank pane.
//
// The head's row id (a random PK) can go stale between the sections snapshot and the click:
// its INBOX/label copy may be archived or purged+re-inserted with a fresh id during a
// resync. A click that lands on a falsy or 404'd id must never silently do nothing — it
// warns, self-heals the snapshot via onMiss (a sections refetch), and retries once by
// resolving the row's thread and matching the stable message_id. thread/getThread/onMiss
// are optional so a bare (id, {getMessage,...}) call still degrades gracefully.
export async function openDeepLinkMessage(id: string | null | undefined, {
  getMessage, setThreadMessages, setSelectedMessage,
  thread, getThread, onMiss,
}: {
  getMessage: (id: string) => Promise<(GtdThread & { id: string }) | null>;
  setThreadMessages: (key: string, messages: GtdThread[]) => void;
  setSelectedMessage: (id: string) => void;
  thread?: { thread_key?: string; message_id?: string } | null;
  getThread?: (key: string) => Promise<{ messages: Array<GtdThread & { id: string }> }>;
  onMiss?: () => void;
}) {
  const seq = ++_deepLinkSeq;
  const open = (msg: GtdThread & { id: string }) => {
    // A newer click superseded this one while we awaited the fetch — losing the race is
    // not an error, so drop the stale write silently (no warn). Guards every state write,
    // including the recovery path below.
    if (seq !== _deepLinkSeq) return null;
    setThreadMessages(`__dl_${msg.id}`, [msg]);
    setSelectedMessage(msg.id);
    return msg;
  };

  if (id) {
    try {
      const msg = await getMessage(id);
      if (msg) return open(msg);
    } catch {
      // Fall through to recovery — a 404 here means the snapshot id is stale.
    }
  }

  console.warn(`GTD deep-link miss (id=${id ?? 'null'}, thread_key=${thread?.thread_key ?? 'null'}); refetching sections`);
  onMiss?.();

  if (getThread && thread?.thread_key) {
    try {
      const { messages } = await getThread(thread.thread_key);
      const msg = pickThreadMessage(messages, thread.message_id);
      if (msg) return open(msg);
    } catch {
      // Best-effort; the onMiss refetch still refreshes the ids for the next click.
    }
  }
  return null;
}

// Frame math for the Inbox-Zero pet sprite. Given a cached pet's descriptor
// (grid + frame size + static frame + hover sequence) and a target render size,
// return the pixel layout the GtdZeroPet CSS needs: the scaled frame size, the full
// background-size, the at-rest static frame position, and the horizontal hover run
// (background-position-x from → to over `hoverCount` steps, on a single row).
// Pure and DOM-free so the frame math is unit-testable.
export function computeSpriteLayout({ cols = 1, rows = 1, frameW = 1, frameH = 1, staticFrame = 0, hover, size = 104 }: {
  cols?: number;
  rows?: number;
  frameW?: number;
  frameH?: number;
  staticFrame?: number;
  hover?: { start?: number; count?: number };
  size?: number;
} = {}) {
  const c = Math.max(1, Math.trunc(cols) || 1);
  const r = Math.max(1, Math.trunc(rows) || 1);
  const fw = frameW > 0 ? frameW : 1;
  const fh = frameH > 0 ? frameH : 1;
  const scale = size / Math.max(fw, fh);
  const dispW = fw * scale;
  const dispH = fh * scale;
  const frameCount = c * r;

  const sf = Math.max(0, Math.min(frameCount - 1, Math.trunc(staticFrame) || 0));
  const staticX = -((sf % c) * dispW);
  const staticY = -(Math.floor(sf / c) * dispH);

  const hStart = Math.max(0, Math.min(frameCount - 1, Math.trunc(hover?.start ?? 0) || 0));
  const hRow = Math.floor(hStart / c);
  const hCol = hStart % c;
  // Clamp the sequence to the rest of its row — the CSS animates only
  // background-position-x, so a hover loop lives on one row.
  const hCount = Math.max(1, Math.min(Math.trunc(hover?.count ?? c) || c, c - hCol));

  // Normalise -0 (from -(0 * …)) to 0 so it never reaches the CSS as "-0px".
  const nz = (v: number) => (v === 0 ? 0 : v);

  return {
    dispW, dispH,
    bgW: c * dispW,
    bgH: r * dispH,
    staticX: nz(staticX), staticY: nz(staticY),
    hoverY: nz(-(hRow * dispH)),
    hoverX0: nz(-(hCol * dispW)),
    hoverX1: nz(-((hCol + hCount) * dispW)),
    hoverCount: hCount,
  };
}

import { sanitizeFolderOrder } from '../utils/sidebar.ts';

const STORAGE_KEY = 'mailflow_folder_order';

interface FolderOrderPreferences {
  folderOrder?: unknown;
}

export function cacheFolderOrder(value: unknown, storage = localStorage) {
  const clean = sanitizeFolderOrder(value);
  storage.setItem(STORAGE_KEY, JSON.stringify(clean));
  return clean;
}

export function readFolderOrder(storage = localStorage) {
  try {
    return sanitizeFolderOrder(
      JSON.parse(storage.getItem(STORAGE_KEY) || '{}'),
    );
  } catch {
    return {};
  }
}

export function cacheFolderOrderFromPreferences(
  preferences: FolderOrderPreferences,
  storage = localStorage,
) {
  return cacheFolderOrder(preferences.folderOrder, storage);
}

export function mergeFolderOrder(
  current: unknown,
  accountId: string,
  paths: unknown,
  storage = localStorage,
) {
  return cacheFolderOrder({
    ...sanitizeFolderOrder(current),
    [accountId]: Array.isArray(paths) ? paths : [],
  }, storage);
}

import { onAuthEpochChange } from './authEpoch.ts';
// pendingMarkReadMap: messageId → accountId for PATCHes that are still in-flight.
// Used by useWebSocket to adjust unread counts before the server has committed.
export const pendingMarkReadMap = new Map<string, string>();

// completedMarkReadMap: messageId → accountId for PATCHes that returned successfully
// but whose DB write may not yet be visible to a concurrent getMessages SELECT.
// Entries expire after 10s — long enough to cover any in-flight getMessages response
// that raced with the mark-read commit.
export const completedMarkReadMap = new Map<string, string>();

// Safety timeout handles keyed by messageId — cancels the previous timer if the
// same messageId is re-used before the old one fires, preventing a stale timer
// from deleting a newer in-flight entry for the same message.
const _pendingTimers = new Map<string, ReturnType<typeof setTimeout>>();
const _completedTimers = new Map<string, ReturnType<typeof setTimeout>>();

// Set a pending entry with a 30-second safety timeout.
// Callers still call pendingMarkReadMap.delete() on success/error; the timeout
// is a fallback so a hung or abandoned request never leaves a permanent entry.
export function setPending(messageId: string, accountId: string): void {
  const prev = _pendingTimers.get(messageId);
  if (prev) clearTimeout(prev);
  const timer = setTimeout(() => {
    pendingMarkReadMap.delete(messageId);
    _pendingTimers.delete(messageId);
  }, 30000);
  _pendingTimers.set(messageId, timer);
  pendingMarkReadMap.set(messageId, accountId);
}

onAuthEpochChange(() => {
  for (const timer of _pendingTimers.values()) clearTimeout(timer);
  _pendingTimers.clear();
  for (const timer of _completedTimers.values()) clearTimeout(timer);
  _completedTimers.clear();
  pendingMarkReadMap.clear();
  completedMarkReadMap.clear();
});

/** A version-fenced authoritative readback releases both optimistic badge guards. */
export function clearReadGuards(messageId: string): void {
  const timer = _pendingTimers.get(messageId);
  if (timer) clearTimeout(timer);
  _pendingTimers.delete(messageId);
  const completedTimer = _completedTimers.get(messageId);
  if (completedTimer) clearTimeout(completedTimer);
  _completedTimers.delete(messageId);
  pendingMarkReadMap.delete(messageId);
  completedMarkReadMap.delete(messageId);
}

/** A newer confirmation cancels the preceding expiry callback for this copy. */
export function setCompletedRead(messageId: string, accountId: string): void {
  clearReadGuards(messageId);
  completedMarkReadMap.set(messageId, accountId);
  const timer = setTimeout(() => {
    if (_completedTimers.get(messageId) !== timer) return;
    _completedTimers.delete(messageId);
    completedMarkReadMap.delete(messageId);
  }, 10000);
  _completedTimers.set(messageId, timer);
}

import i18n from 'i18next';

export type MailMutationStatus = 'confirmed' | 'pending' | 'failed';

/** HTTP success describes the request; only per-item confirmation describes a write. */
export function mailMutationStatus(response: unknown, id: string): MailMutationStatus {
  if (!response || typeof response !== 'object') return 'pending';
  const value = response as Record<string, unknown>;
  const includes = (field: string) => Array.isArray(value[field]) && value[field].includes(id);
  const outcomes = Array.isArray(value.outcomes) ? value.outcomes : [];
  const outcome = outcomes.find((item: unknown) => typeof item === 'object' && item !== null && 'id' in item && item.id === id);
  const status: unknown = outcome && typeof outcome === 'object' && 'status' in outcome ? outcome.status : undefined;
  if (includes('failed') || ['failed', 'permanent', 'conflict', 'cancelled'].includes(String(status)) || value.ok === false) return 'failed';
  if (includes('pending')) return 'pending';
  if (status !== undefined) return ['confirmed', 'succeeded', 'updated'].includes(String(status)) ? 'confirmed' : 'pending';
  if (includes('updated')) return 'confirmed';
  const structured = ['updated', 'pending', 'failed', 'outcomes'].some(key => key in value);
  return !structured && value.ok === true ? 'confirmed' : 'pending';
}

export function mailMutationFailure(error: unknown): 'failed' | 'pending' {
  const status = typeof error === 'object' && error !== null && 'status' in error ? Number(error.status) : 0;
  return status >= 400 && status < 500 && status !== 408 && status !== 429 ? 'failed' : 'pending';
}

/** Use the initialized i18next singleton without importing browser bootstrap. */
export function mutationNotice(status: 'pending' | 'failed') {
  if (status === 'pending') return {
    title: i18n.isInitialized ? String(i18n.t('mailStateChange.pendingTitle')) : 'Mail change pending',
    body: i18n.isInitialized ? String(i18n.t('mailStateChange.pendingBody')) : 'The mail provider has not confirmed this change yet. The current mailbox state will be checked again.',
  };
  return {
    title: i18n.isInitialized ? String(i18n.t('mailStateChange.failedTitle')) : 'Mail change failed',
    body: i18n.isInitialized ? String(i18n.t('mailStateChange.failedBody')) : 'The mail provider could not apply this change. The previous state has been restored.',
  };
}

// One vector master for app chrome, favicons and generated installation assets.
export const BRAND_ACCENT = '#35558a';
export const BRAND_ENVELOPE = 'M7 12.5 16 6.5 25 12.5V23a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2Z';
export const BRAND_FOLD = 'm7 12.5 9 6 9-6M7.5 24l6.5-6M24.5 24 18 18';
export function brandSvg(accent = BRAND_ACCENT, { maskable = false, badge = false } = {}) {
  // Accent can originate from custom CSS. Escape XML attribute delimiters.
  const color = String(accent).replace(/[&<>"']/g, char => {
    switch (char) {
      case '&': return '&amp;';
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '"': return '&quot;';
      case "'": return '&apos;';
      default: return char;
    }
  });
  const symbol = `<path d="${BRAND_ENVELOPE}" fill="none" stroke="#fff" stroke-width="1.8" stroke-linejoin="round"/><path d="${BRAND_FOLD}" fill="none" stroke="#fff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">${badge ? '' : `<rect width="32" height="32" rx="${maskable ? 0 : 7.5}" fill="${color}"/>`}<g${maskable ? ' transform="translate(4 4) scale(.75)"' : ''}>${symbol}</g></svg>`;
}

import { getAuthEpoch, isCurrentAuthEpoch } from '../authEpoch.ts';
import { CSRF_HEADER, CSRF_VALUE } from '../api.ts';
import { PREVIEW_LIMIT } from './types.ts';
export type ProcessingAction = 'probe' | 'unlock' | 'eml-parse' | 'eml-part' | 'cards' | 'scan' | 'signatures' | 'archive-index' | 'archive-extract';
/** The server processes only these supplied bytes; it never fetches a client-supplied URL. */
export async function processAttachment(blob: Blob, action: ProcessingAction, fields: Record<string, string>, signal: AbortSignal): Promise<Response> {
  const epoch = getAuthEpoch();
  signal.throwIfAborted(); if (blob.size > PREVIEW_LIMIT) throw new Error('LIMIT');
  const body = new FormData(); body.append('file', blob, 'attachment');
  for (const [name, value] of Object.entries(fields)) body.append(name, value);
  const response = await fetch(`/api/mail/attachments/process/${action}`, { method: 'POST', credentials: 'include', cache: 'no-store', headers: { [CSRF_HEADER]: CSRF_VALUE }, body, signal });
  if (!isCurrentAuthEpoch(epoch)) throw new DOMException('Preview cancelled', 'AbortError');
  if (!response.ok) {
    const result: unknown = await response.json().catch(() => null);
    const code = result && typeof result === 'object' && 'code' in result && typeof result.code === 'string' ? result.code : 'UNAVAILABLE';
    throw new Error(code);
  }
  signal.throwIfAborted(); return response;
}
export function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('CORRUPT');
  return value as Record<string, unknown>;
}
export function textValue(value: unknown): string { return typeof value === 'string' ? value : ''; }

/** A throwable with the optional fields the UI reads (HTTP status, API code). */
export interface AppError extends Error {
  status?: number;
  code?: string;
}

/**
 * Narrow an unknown catch value. Thrown values are normally Error instances; anything else is
 * wrapped so callers can read `.message`/`.status` without a scattered unknown check.
 */
export function toAppError(value: unknown): AppError {
  if (value instanceof Error) return value as AppError;
  return new Error(String(value)) as AppError;
}

interface SidebarFolderNode {
  path: string;
  name?: string;
  delimiter?: string;
  special_use?: string | null;
  account_id?: string;
  children: SidebarFolderNode[];
  [key: string]: unknown;
}

export function collapsedTooltip(label: string | null | undefined, collapsed: boolean): string | undefined {
  if (!collapsed) return undefined;
  // An empty title suppresses the browser's own tooltip, so drop the attribute.
  return label?.trim() || undefined;
}

export function activateOnKey(activate: () => void): (event: { key: string; preventDefault(): void }) => void {
  return (event: { key: string; preventDefault(): void }) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    event.preventDefault(); // Space would otherwise scroll the page.
    activate();
  };
}

export const FOLDER_ORDER_DRAG_TYPE = 'application/x-mailflow-folder-order';

function delimiterFor(folders: Array<{ delimiter?: string; [key: string]: unknown }>): string {
  return folders.find(folder => (
    typeof folder?.delimiter === 'string' && folder.delimiter
  ))?.delimiter || '/';
}

function folderParent(path: string, delimiter: string): string | null {
  const index = path.lastIndexOf(delimiter);
  return index === -1 ? null : path.slice(0, index);
}

function folderPathsWithAncestors(folders: Array<{ path: string; [key: string]: unknown }>): string[] {
  const delimiter = delimiterFor(folders);
  const paths = new Set<string>();
  for (const folder of folders) {
    if (typeof folder?.path !== 'string' || !folder.path) continue;
    const parts = folder.path.split(delimiter);
    for (let depth = 1; depth <= parts.length; depth += 1) {
      paths.add(parts.slice(0, depth).join(delimiter));
    }
  }
  return [...paths].sort((a, b) => a.localeCompare(b));
}

export function sanitizeFolderOrder(value: unknown): Record<string, string[]> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const clean: Record<string, string[]> = {};
  for (const [accountId, paths] of Object.entries(value)) {
    if (!Array.isArray(paths)) continue;
    const seen = new Set();
    const valid = paths.filter(path => {
      if (typeof path !== 'string' || !path || seen.has(path)) return false;
      seen.add(path);
      return true;
    });
    clean[accountId] = valid;
  }
  return clean;
}

export function normalizeFolderOrder(folders: Array<{ path: string; [key: string]: unknown }> | null | undefined, savedOrder: string[] = []): string[] {
  const known = folderPathsWithAncestors(Array.isArray(folders) ? folders : []);
  const knownSet = new Set(known);
  const ranked: string[] = [];
  const seen = new Set();
  if (Array.isArray(savedOrder)) {
    for (const folderPath of savedOrder) {
      if (
        typeof folderPath !== 'string'
        || seen.has(folderPath)
        || !knownSet.has(folderPath)
      ) continue;
      seen.add(folderPath);
      ranked.push(folderPath);
    }
  }
  return [...ranked, ...known.filter(folderPath => !seen.has(folderPath))];
}

export function buildFolderTree(
  folders: Array<{ path: string; account_id?: string; delimiter?: string; [key: string]: unknown }> | null | undefined,
  savedOrder: string[] = [],
): SidebarFolderNode[] {
  const safeFolders = Array.isArray(folders) ? folders : [];
  const delimiter = delimiterFor(safeFolders);
  const map: Record<string, SidebarFolderNode> = {};
  for (const folder of safeFolders) {
    if (typeof folder?.path !== 'string' || !folder.path) continue;
    map[folder.path] = { ...folder, children: [] };
  }

  for (const folder of safeFolders) {
    if (typeof folder?.path !== 'string' || !folder.path) continue;
    const parts = folder.path.split(delimiter);
    for (let depth = 1; depth < parts.length; depth += 1) {
      const folderPath = parts.slice(0, depth).join(delimiter);
      if (!map[folderPath]) {
        map[folderPath] = {
          path: folderPath,
          name: parts[depth - 1],
          delimiter,
          special_use: null,
          account_id: folder.account_id,
          children: [],
        };
      }
    }
  }

  const roots: SidebarFolderNode[] = [];
  const nodes = Object.values(map).sort((a, b) => a.path.localeCompare(b.path));
  for (const node of nodes) {
    const parentPath = folderParent(node.path, delimiter);
    if (parentPath && map[parentPath] && parentPath !== node.path) {
      map[parentPath].children.push(node);
    } else {
      roots.push(node);
    }
  }

  const rank = new Map(
    normalizeFolderOrder(safeFolders, savedOrder)
      .map((folderPath, index) => [folderPath, index]),
  );
  const sortGroup = (group: SidebarFolderNode[]): void => {
    group.sort((a, b) => {
      const aRank = rank.get(a.path);
      const bRank = rank.get(b.path);
      if (aRank != null && bRank != null) return aRank - bRank;
      if (aRank != null) return -1;
      if (bRank != null) return 1;
      return a.path.localeCompare(b.path);
    });
    group.forEach(node => sortGroup(node.children));
  };
  sortGroup(roots);
  return roots;
}

export function reorderFolderPaths(
  folders: Array<{ path: string; delimiter?: string; [key: string]: unknown }>,
  savedOrder: string[],
  draggedPath: string,
  targetPath: string,
  position: unknown,
): string[] | null {
  if (position !== 'before' && position !== 'after') return null;
  const safeFolders = Array.isArray(folders) ? folders : [];
  const delimiter = delimiterFor(safeFolders);
  const current = normalizeFolderOrder(safeFolders, savedOrder);
  const known: Set<string> = new Set(current);
  if (
    draggedPath === targetPath
    || !known.has(draggedPath)
    || !known.has(targetPath)
    || folderParent(draggedPath, delimiter) !== folderParent(targetPath, delimiter)
  ) return null;

  const next = current.filter(folderPath => folderPath !== draggedPath);
  const targetIndex = next.indexOf(targetPath);
  next.splice(targetIndex + (position === 'after' ? 1 : 0), 0, draggedPath);
  return next.every((folderPath, index) => folderPath === current[index])
    ? null
    : next;
}

export function folderDropPosition(clientY: number, rect: { top: number; height: number }): 'before' | 'after' {
  return clientY < rect.top + rect.height / 2 ? 'before' : 'after';
}

export function resolveFolderOrderDrop(
  folders: Array<{ path: string; delimiter?: string; [key: string]: unknown }>,
  savedOrder: string[],
  dataTransfer: { types?: readonly string[]; getData?: (type: string) => string } | null,
  targetAccountId: string | number,
  targetPath: string,
  clientY: number,
  rect: { top: number; bottom?: number; height: number; [key: string]: unknown },
): string[] | null {
  if (
    !Array.from(dataTransfer?.types || []).includes(FOLDER_ORDER_DRAG_TYPE)
    || typeof dataTransfer?.getData !== 'function'
  ) return null;

  let drag;
  try {
    drag = JSON.parse(dataTransfer.getData(FOLDER_ORDER_DRAG_TYPE));
  } catch {
    return null;
  }
  if (
    !drag
    || drag.accountId !== targetAccountId
    || typeof drag.path !== 'string'
  ) return null;

  return reorderFolderPaths(
    folders,
    savedOrder,
    drag.path,
    targetPath,
    folderDropPosition(clientY, rect),
  );
}

import lookup from 'void-elements'
